package microposts

import (
	"time"
)

type Post struct {
	text      string
	author    address
	createdAt time.Time
}

func (p Post) String() string {
	out := p.text + "\n"
	out += "_" + p.createdAt.Format("02 Jan 2006, 15:04") + ", by " + p.author.String() + "_"
	return out
}

package microposts

import (
	"chain/runtime/unsafe"
	"strconv"
	"time"
)

var posts []*Post

func CreatePost(text string) {
	posts = append(posts, &Post{
		text:      text,
		author:    unsafe.PreviousRealm().Address(), // provided by env
		createdAt: time.Now(),
	})
}

func Render(_ string) string {
	out := "# Posts\n"
	for i := len(posts) - 1; i >= 0; i-- {
		out += "### Post " + strconv.Itoa(i) + "\n" + posts[i].String()
	}
	return out
}

package millipede

import (
	"strconv"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

const (
	minSize     = 1
	defaultSize = 20
	maxSize     = 100
)

func Draw(size int) string {
	if size < minSize || size > maxSize {
		panic("invalid millipede size")
	}
	paddings := []string{"  ", " ", "", " ", "  ", "   ", "    ", "    ", "   "}
	var b strings.Builder
	b.WriteString("    ╚⊙ ⊙╝\n")
	for i := 0; i < size; i++ {
		b.WriteString(paddings[i%9] + "╚═(███)═╝\n")
	}
	return b.String()
}

func Render(path string) string {
	size := defaultSize

	path = strings.TrimSpace(path)
	if path != "" {
		var err error
		size, err = strconv.Atoi(path)
		if err != nil {
			panic(err)
		}
	}

	output := "```\n" + Draw(size) + "```\n"
	if size > minSize {
		output += ufmt.Sprintf("[%d](/r/demo/art/millipede:%d)< ", size-1, size-1)
	}
	if size < maxSize {
		output += ufmt.Sprintf(" >[%d](/r/demo/art/millipede:%d)", size+1, size+1)
	}
	return output
}

// based on https://github.com/getmillipede/millipede-go/blob/977f046c39c35a650eac0fd30245e96b22c7803c/main.go

// Package vault demonstrates a minimal time-locked token vault built on top of
// the grc20 token package. Deposited tokens are held at the realm's own
// address; withdrawing them is a two-step process: Unvault marks an amount for
// withdrawal and starts a lock timer, then (once the lock elapses) Redeem moves
// the tokens back to the depositor.
package vault

import (
	"chain/runtime"
	"chain/runtime/unsafe"

	tokens "gno.land/p/demo/tokens/grc20"
)

// test1 receives the initial mint at construction.
var test1 = address("g1jg8mtutu9khhfwc4nxmuhcpftf0pajdhfvsqf5")

// lockDuration is the number of blocks that must pass between Unvault and
// Redeem.
const lockDuration = int64(100)

// Token and FooVault-equivalent state are exported for reading; privateLedger
// stays unexported (unrestricted mint/burn/transfer).
var (
	Token         *tokens.Token
	privateLedger *tokens.PrivateLedger
	vaultAddr     address // address holding all deposited tokens

	vaulted   = map[address]uint{}    // still-locked deposits per owner
	pending   = map[address]uint{}    // amount marked for withdrawal
	unlockAt  = map[address]int64{}    // block height at which pending unlocks
	recoverOf = map[address]address{}  // recovery address per depositor
)

func init(cur realm) {
	// generate the token and mint some tokens to test1.
	Token, privateLedger = tokens.NewToken("Foo Token", "FOO", 4, 0, cur)
	privateLedger.Mint(test1, 100000000)

	// the vault holds deposited tokens at the realm's own address.
	vaultAddr = cur.Address()
}

func MyBalance() int64 {
	return Token.BalanceOf(unsafe.OriginCaller())
}

// Deposit moves amount tokens from the caller into the vault, recording a
// recovery address for later use.
func Deposit(cur realm, amount uint, recoverAddress address) {
	caller := unsafe.OriginCaller()
	if err := privateLedger.Transfer(caller, vaultAddr, int64(amount)); err != nil {
		panic(err)
	}
	vaulted[caller] += amount
	recoverOf[caller] = recoverAddress
}

// Recover sends target's still-locked deposit to its recorded recovery address.
func Recover(cur realm, target address) {
	amount := vaulted[target]
	if amount == 0 {
		return
	}
	dest := recoverOf[target]
	if err := privateLedger.Transfer(vaultAddr, dest, int64(amount)); err != nil {
		panic(err)
	}
	vaulted[target] = 0
}

// Unvault marks amount of the caller's deposit for withdrawal and starts the
// lock timer.
func Unvault(cur realm, amount uint) {
	caller := unsafe.OriginCaller()
	if vaulted[caller] < amount {
		panic("insufficient vaulted balance")
	}
	vaulted[caller] -= amount
	pending[caller] += amount
	unlockAt[caller] = runtime.ChainHeight() + lockDuration
}

// Redeem transfers amount of the caller's matured pending withdrawal back to
// the caller.
func Redeem(cur realm, amount uint) {
	caller := unsafe.OriginCaller()
	if pending[caller] < amount {
		panic("insufficient pending balance")
	}
	if runtime.ChainHeight() < unlockAt[caller] {
		panic("still locked")
	}
	if err := privateLedger.Transfer(vaultAddr, caller, int64(amount)); err != nil {
		panic(err)
	}
	pending[caller] -= amount
}

// based on Wikipedia's Solidity example: https://en.wikipedia.org/wiki/Solidity
package wikicoin

import (
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

var balances = avl.NewTree() // addr -> balance
var minter address

// Constructor code is only run when the contract is created
func init() {
	minter = unsafe.OriginCaller()
}

func Mint(cur realm, receiver address, amount uint) {
	if unsafe.OriginCaller() != minter {
		panic("restricted")
	}
	curBalance := BalanceOf(receiver)
	newBalance := curBalance + amount
	balances.Set(receiver.String(), newBalance)
}

func Send(cur realm, receiver address, amount uint) {
	sender := unsafe.OriginCaller()
	senderBalance := BalanceOf(sender)
	if amount > senderBalance {
		panic(ufmt.Sprintf("insufficient balance: %d", senderBalance))
	}
	receiverBalance := BalanceOf(receiver)
	balances.Set(sender.String(), senderBalance-amount)
	balances.Set(receiver.String(), receiverBalance+amount)
}

func BalanceOf(addr address) uint {
	balance := balances.Get(addr.String())
	if balance == nil {
		return 0
	}
	return balance.(uint)
}

// Package hello is a canary realm: it proves the end-to-end pipeline (workspace
// resolution of a versioned local dependency, gno test, gno lint, and CI)
// works from the very first commit. It has no external dependencies. Remove it
// once real realms land.
package hello

import (
	"strings"

	"gno.land/p/moul/greet/v1"
)

// greets counts how many times Greet has been called (persistent state).
var greets int

// Greet records a greeting from the caller and returns it. Crossing function:
// it mutates persistent state, so it takes `cur realm` per the gno 0.9
// interrealm convention.
func Greet(cur realm, name string) string {
	greets++
	return greet.Greet(name)
}

// Count returns how many greetings have been recorded. Read-only.
func Count() int { return greets }

// Render is the gnoweb Markdown view.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# r/moul/hello/v1\n\n")
	b.WriteString("Canary realm for the gno-contracts repository.\n\n")
	b.WriteString("- Greetings recorded: ")
	b.WriteString(itoa(greets))
	b.WriteString("\n")
	return b.String()
}

// itoa avoids importing strconv for a single conversion in the canary.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

package outfmt

import (
	"math/rand"
	"strconv"
	"strings"

	"gno.land/p/nt/ufmt/v0"
)

type Result struct {
	Number  int
	Text    string
	Numbers []int
}

func (res *Result) String() string {
	output := ufmt.Sprintf("Text: %s\n", res.Text)
	output += ufmt.Sprintf("Number: %d\n", res.Number)

	output += "Numbers:"
	for _, number := range res.Numbers {
		output += ufmt.Sprintf(" %d", number)
	}
	output += "\n"

	return output
}

var rSeed = rand.NewPCG(0, 0)

func genResult() Result {
	r := rand.New(rSeed)

	// init rand
	res := Result{
		Text:   "Hello Gnomes!",
		Number: r.IntN(1000),
	}

	length := r.IntN(8) + 2
	res.Numbers = make([]int, length)
	for i := 0; i < length; i++ {
		res.Numbers[i] = r.IntN(100)
	}

	return res
}

// marshal function to manually convert struct to JSON string
func (r Result) marshal() string {
	// Start JSON string
	jsonStr := `{"Number":` + strconv.Itoa(r.Number) + `,"Text":"` + r.Text + `","Numbers":[`

	for i, num := range r.Numbers {
		jsonStr += strconv.Itoa(num)
		if i < len(r.Numbers)-1 {
			jsonStr += ","
		}
	}

	jsonStr += "]}"

	return jsonStr
}

func Render(path string) string {
	if path == "" {
		output := ""
		output += "* [?fmt=stringer](/r/moul/outfmt:?fmt=stringer)\n"
		output += "* [?fmt=json](/r/moul/outfmt:?fmt=json)\n"
		output += "* [?fmt=jsonp](/r/moul/outfmt:?fmt=jsonp)\n"
		return output
	}

	// parsing
	fmt := "stringer" // default
	// FIXME: whitelist and use net/url.
	{
		parts := strings.Split(path, "?")
		if len(parts) == 2 {
			// path := parts[0]
			query := parts[1]
			if query != "" {
				parts = strings.Split(query, "=")
				if len(parts) == 2 {
					k := parts[0]
					v := parts[1]
					if k == "fmt" {
						fmt = v
					}
				}
			}
		}
	}

	// rendering

	res := genResult()
	switch fmt {
	case "stringer":
		return res.String()
	case "json":
		// FIXME: return content-type?
		out := res.marshal()
		return string(out)
	case "jsonp":
		// FIXME: return content-type?
		callback := "callback" // FIXME: get it from query
		out := res.marshal()
		return callback + "(" + string(out) + ")"
	default:
		panic("unknown format")
	}
}

func checkErr(err error) {
	if err != nil {
		panic(err)
	}
}

package sapin

import "strconv"

const defaultSize int = 3

func Render(path string) string {
	size := defaultSize

	if path != "" {
		var err error
		size, err = strconv.Atoi(path)
		if err != nil {
			panic(err)
		}
	}

	sapin := Sapin(size)
	output := "```\n" + sapin + "```\n"
	return output
}

package sapin

import "strings"

func Sapin(size int) string {
	if size < 1 {
		return ""
	}
	var b strings.Builder
	for floor := 0; floor < size; floor++ {
		for j := 0; j < floor+4; j++ {
			spaces := size*2 - (floor-1)*2 - j + size - 2
			bodies := j*2 + 1 + floor*4
			b.WriteString(strings.Repeat(" ", spaces))
			b.WriteString(strings.Repeat("*", bodies))
			b.WriteString("\n")
		}
	}

	for i := 0; i < size; i++ {
		spaces := (size-1)*3 + 2
		b.WriteString(strings.Repeat(" ", spaces))
		b.WriteString("|||\n")
	}
	return b.String()
}

// Package blog is a multi-author on-chain blog realm for gno.land.
//
// Any caller can Publish a post; posts are stored persistently and rendered
// newest-first. Each post records its author (the calling address) and the
// block height at which it was published.
package blog

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// Post is a single blog entry.
type Post struct {
	ID     int
	Title  string
	Body   string
	Author address
	Height int64
}

// posts holds every published post keyed by its zero-padded id (for
// deterministic ordering) and nextID is the id assigned to the next post.
var (
	posts  avl.Tree // key: zero-padded id string -> *Post
	nextID int
)

// key returns a fixed-width, zero-padded key so avl.Tree iteration is ordered
// by numeric id (and thus by publication order).
func key(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

// Publish creates a new post authored by the caller and returns its id.
// It is a state-mutating exported function, so it takes `cur realm`.
func Publish(cur realm, title string, body string) int {
	title = strings.TrimSpace(title)
	body = strings.TrimSpace(body)
	if title == "" {
		panic("blog: title must not be empty")
	}
	if body == "" {
		panic("blog: body must not be empty")
	}

	id := nextID
	nextID++

	p := &Post{
		ID:     id,
		Title:  title,
		Body:   body,
		Author: unsafe.PreviousRealm().Address(),
		Height: runtime.ChainHeight(),
	}
	posts.Set(key(id), p)

	chain.Emit(
		"PostPublished",
		"id", strconv.Itoa(id),
		"author", p.Author.String(),
	)
	return id
}

// PostCount returns the number of published posts.
func PostCount() int {
	return posts.Size()
}

// snippet returns a short one-line preview of the body.
func snippet(body string) string {
	// collapse newlines so the preview stays on a single markdown line
	s := strings.ReplaceAll(body, "\n", " ")
	s = strings.TrimSpace(s)
	const max = 140
	if len(s) > max {
		return s[:max] + "…"
	}
	return s
}

// Render lists all posts newest-first at the root, or a single post's full
// text at path "/<id>". Render is NOT a crossing function.
func Render(path string) string {
	path = strings.TrimSpace(path)
	if path == "" || path == "/" {
		return renderList()
	}
	idStr := strings.TrimPrefix(path, "/")
	id, err := strconv.Atoi(idStr)
	if err != nil {
		return "# Not found\n\nInvalid post path: `" + path + "`\n\n[← back](/r/REPLACE_ADDR/blog)\n"
	}
	v := posts.Get(key(id))
	if v == nil {
		return "# Not found\n\nNo post with id " + idStr + ".\n\n[← back](/r/REPLACE_ADDR/blog)\n"
	}
	return renderPost(v.(*Post))
}

func renderList() string {
	var b strings.Builder
	b.WriteString("# 📝 Blog\n\n")
	if posts.Size() == 0 {
		b.WriteString("_No posts yet. Be the first to `Publish`._\n")
		return b.String()
	}
	b.WriteString(strconv.Itoa(posts.Size()) + " post(s), newest first.\n\n")

	// avl iterates ascending; iterate in reverse for newest-first.
	posts.ReverseIterate("", "", func(_ string, v interface{}) bool {
		p := v.(*Post)
		b.WriteString("## [")
		b.WriteString(p.Title)
		b.WriteString("](/r/REPLACE_ADDR/blog:/")
		b.WriteString(strconv.Itoa(p.ID))
		b.WriteString(")\n\n")
		b.WriteString("by `")
		b.WriteString(p.Author.String())
		b.WriteString("` · height ")
		b.WriteString(strconv.FormatInt(p.Height, 10))
		b.WriteString("\n\n")
		b.WriteString(snippet(p.Body))
		b.WriteString("\n\n---\n\n")
		return false
	})
	return b.String()
}

func renderPost(p *Post) string {
	var b strings.Builder
	b.WriteString("# ")
	b.WriteString(p.Title)
	b.WriteString("\n\n")
	b.WriteString("by `")
	b.WriteString(p.Author.String())
	b.WriteString("` · height ")
	b.WriteString(strconv.FormatInt(p.Height, 10))
	b.WriteString("\n\n")
	b.WriteString(p.Body)
	b.WriteString("\n\n---\n\n[← back to all posts](/r/REPLACE_ADDR/blog)\n")
	return b.String()
}

package calc

import (
	"chain"
	"errors"
	"strconv"
	"strings"
)

// stack holds the shared RPN operand stack, bottom (index 0) to top.
var stack []int

// ErrUnderflow is raised when an operator needs more operands than available.
var ErrUnderflow = errors.New("stack underflow: operator needs two operands")

// ErrDivByZero is raised on division by zero.
var ErrDivByZero = errors.New("division by zero")

// Push consumes a single token: an integer is pushed onto the stack; an
// operator (+, -, *, /) pops two operands and pushes the result.
func Push(cur realm, token string) {
	token = strings.TrimSpace(token)
	if token == "" {
		panic("empty token")
	}

	switch token {
	case "+", "-", "*", "/":
		if len(stack) < 2 {
			panic(ErrUnderflow.Error())
		}
		b := stack[len(stack)-1]
		a := stack[len(stack)-2]
		stack = stack[:len(stack)-2]

		var r int
		switch token {
		case "+":
			r = a + b
		case "-":
			r = a - b
		case "*":
			r = a * b
		case "/":
			if b == 0 {
				panic(ErrDivByZero.Error())
			}
			r = a / b
		}
		stack = append(stack, r)
		chain.Emit("Op", "op", token, "result", strconv.Itoa(r))
	default:
		n, err := strconv.Atoi(token)
		if err != nil {
			panic("invalid token: expected integer or one of + - * /, got " + token)
		}
		stack = append(stack, n)
		chain.Emit("Push", "value", strconv.Itoa(n))
	}
}

// Clear empties the shared stack.
func Clear(cur realm) {
	stack = nil
	chain.Emit("Clear")
}

// Depth returns the number of values currently on the stack.
func Depth() int {
	return len(stack)
}

// Top returns the top value and whether the stack is non-empty.
func Top() (int, bool) {
	if len(stack) == 0 {
		return 0, false
	}
	return stack[len(stack)-1], true
}

// Render renders the current stack, the top value as the result, and a
// short usage guide.
func Render(path string) string {
	var sb strings.Builder
	sb.WriteString("# RPN Calculator\n\n")

	sb.WriteString("## Result\n\n")
	if top, ok := Top(); ok {
		sb.WriteString("**")
		sb.WriteString(strconv.Itoa(top))
		sb.WriteString("**\n\n")
	} else {
		sb.WriteString("_(empty stack)_\n\n")
	}

	sb.WriteString("## Stack (bottom → top)\n\n")
	if len(stack) == 0 {
		sb.WriteString("_empty_\n\n")
	} else {
		for i, v := range stack {
			sb.WriteString(strconv.Itoa(i))
			sb.WriteString(". ")
			sb.WriteString(strconv.Itoa(v))
			sb.WriteString("\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## Usage\n\n")
	sb.WriteString("Reverse Polish Notation: operands first, operator last.\n\n")
	sb.WriteString("- `Push(\"5\")` then `Push(\"3\")` then `Push(\"+\")` → `8`\n")
	sb.WriteString("- Supported operators: `+`, `-`, `*`, `/` (integer division)\n")
	sb.WriteString("- An operator pops the top two values (a, b) and pushes `a op b`.\n")
	sb.WriteString("- `Clear()` empties the stack.\n")
	sb.WriteString("- Divide-by-zero and underflow abort the transaction.\n")

	return sb.String()
}

// Package coinflipduel is a one-on-one coin-flip duel: challenge another
// address, they call heads or tails, and the block settles it. No stakes,
// just bragging rights tracked in an on-chain win/loss record.
package coinflipduel

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// duelStatus tracks the lifecycle of a duel.
type duelStatus int

const (
	statusPending duelStatus = iota
	statusResolved
	statusCancelled
)

func (s duelStatus) String() string {
	switch s {
	case statusPending:
		return "pending"
	case statusResolved:
		return "resolved"
	case statusCancelled:
		return "cancelled"
	default:
		return "?"
	}
}

// duel is one challenge from Challenger to Opponent over a single coin flip.
// The Challenger calls a side up front; the Opponent's only move is to
// accept, which triggers the flip.
type duel struct {
	ID         string
	Challenger address
	Opponent   address
	Call       string // "heads" or "tails" — the challenger's pick
	Status     duelStatus
	Result     string // "heads" or "tails" once resolved
	Winner     address
	CreatedAt  int64
	ResolvedAt int64
}

// playerState is the persisted win/loss record for one address.
type playerState struct {
	Wins   int
	Losses int
	Duels  int
}

var (
	duels   avl.Tree // duel ID -> *duel
	players avl.Tree // address string -> *playerState

	nextID    int
	flipNonce int
	totalDone int

	champion     address
	championWins int
)

func parseCall(s string) (string, bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "heads", "h":
		return "heads", true
	case "tails", "t":
		return "tails", true
	default:
		return "", false
	}
}

// flipCoin derives a deterministic pseudo-random side from the current chain
// height, a monotonic per-realm nonce, and both duelists' addresses, so two
// duels resolved in the same block still diverge.
func flipCoin(d *duel) string {
	flipNonce++
	seed := runtime.ChainHeight() + int64(flipNonce)
	s := d.Challenger.String() + d.Opponent.String() + d.ID
	for i := 0; i < len(s); i++ {
		seed += int64(s[i])
	}
	if seed < 0 {
		seed = -seed
	}
	if seed%2 == 0 {
		return "heads"
	}
	return "tails"
}

func getOrCreate(addr address) *playerState {
	key := addr.String()
	if v := players.Get(key); v != nil {
		return v.(*playerState)
	}
	ps := &playerState{}
	players.Set(key, ps)
	return ps
}

func recordResult(winner, loser address) {
	w := getOrCreate(winner)
	w.Wins++
	w.Duels++
	l := getOrCreate(loser)
	l.Losses++
	l.Duels++

	if w.Wins > championWins {
		championWins = w.Wins
		champion = winner
	}
}

// Challenge opens a new duel against opponentAddr, locking in the
// challenger's call of "heads"/"tails" ("h"/"t" also accepted). The
// opponent settles it by calling Accept with the returned duel ID.
func Challenge(cur realm, opponentAddr string, call string) string {
	challenger := cur.Previous().Address()

	opponent := address(strings.TrimSpace(opponentAddr))
	if !opponent.IsValid() {
		panic("invalid opponent address")
	}
	if opponent == challenger {
		panic("cannot duel yourself")
	}

	pick, ok := parseCall(call)
	if !ok {
		panic("call must be heads or tails (h/t)")
	}

	nextID++
	id := strconv.Itoa(nextID)
	d := &duel{
		ID:         id,
		Challenger: challenger,
		Opponent:   opponent,
		Call:       pick,
		Status:     statusPending,
		CreatedAt:  runtime.ChainHeight(),
	}
	duels.Set(id, d)

	chain.Emit("DuelChallenged",
		"id", id,
		"challenger", challenger.String(),
		"opponent", opponent.String(),
		"call", pick,
	)

	return "duel #" + id + " created: you called " + pick +
		", waiting for " + opponent.String() + " to accept"
}

// Accept settles a pending duel. Only the challenged opponent may call it;
// the flip happens immediately and the result is final.
func Accept(cur realm, id string) string {
	caller := cur.Previous().Address()

	v := duels.Get(id)
	if v == nil {
		panic("no such duel")
	}
	d := v.(*duel)

	if d.Status != statusPending {
		panic("duel already " + d.Status.String())
	}
	if caller != d.Opponent {
		panic("only the challenged opponent can accept this duel")
	}

	result := flipCoin(d)
	d.Result = result
	d.Status = statusResolved
	d.ResolvedAt = runtime.ChainHeight()

	if result == d.Call {
		d.Winner = d.Challenger
		recordResult(d.Challenger, d.Opponent)
	} else {
		d.Winner = d.Opponent
		recordResult(d.Opponent, d.Challenger)
	}

	totalDone++

	chain.Emit("DuelResolved",
		"id", id,
		"result", result,
		"winner", d.Winner.String(),
	)

	return "the coin landed on " + result + " -- " + d.Winner.String() + " wins duel #" + id
}

// Cancel withdraws a still-pending duel. Only the challenger may cancel,
// and only before the opponent accepts.
func Cancel(cur realm, id string) string {
	caller := cur.Previous().Address()

	v := duels.Get(id)
	if v == nil {
		panic("no such duel")
	}
	d := v.(*duel)

	if d.Status != statusPending {
		panic("duel already " + d.Status.String())
	}
	if caller != d.Challenger {
		panic("only the challenger can cancel this duel")
	}

	d.Status = statusCancelled
	return "duel #" + id + " cancelled"
}

// escapeInline neutralizes markdown-active characters in untrusted text
// before it's embedded inline in Render output.
func escapeInline(s string) string {
	r := strings.NewReplacer(
		"\\", "\\\\",
		"`", "\\`",
		"*", "\\*",
		"_", "\\_",
		"[", "\\[",
		"]", "\\]",
		"|", "\\|",
	)
	return r.Replace(s)
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Coin-Flip Duel\n\n")
	b.WriteString("Challenge another address to a coin flip. You call heads or tails " +
		"up front; they accept and the block decides. No stakes -- just a record.\n\n")
	b.WriteString("- Total duels resolved: " + strconv.Itoa(totalDone) + "\n")

	if champion.IsValid() {
		b.WriteString("- Reigning champion: `" + champion.String() +
			"` (" + strconv.Itoa(championWins) + " wins)\n")
	} else {
		b.WriteString("- No champion yet -- be the first to win a duel.\n")
	}

	b.WriteString("\n## How to play\n\n")
	b.WriteString("1. `Challenge(opponentAddr, \"heads\"|\"tails\")` -- opens a duel, returns its ID.\n")
	b.WriteString("2. The opponent calls `Accept(id)` -- flips the coin and settles it on the spot.\n")
	b.WriteString("3. The challenger may `Cancel(id)` while it's still pending.\n\n")
	b.WriteString("View a duel at this realm's path plus its ID (e.g. `.../coinflipduel:3`), " +
		"or a player's record plus their address (e.g. `.../coinflipduel:g1youraddress...`).\n\n")

	b.WriteString("## Pending duels\n\n")
	pending := 0
	duels.Iterate("", "", func(key string, value interface{}) bool {
		d := value.(*duel)
		if d.Status == statusPending {
			pending++
			b.WriteString("- #" + d.ID + ": `" + d.Challenger.String() + "` called " +
				d.Call + ", waiting on `" + d.Opponent.String() + "`\n")
		}
		return false
	})
	if pending == 0 {
		b.WriteString("_none right now_\n")
	}

	return b.String()
}

func renderDuel(id string) string {
	v := duels.Get(id)
	if v == nil {
		return "# Duel #" + escapeInline(id) + "\n\nNo such duel.\n"
	}
	d := v.(*duel)

	var b strings.Builder
	b.WriteString("# Duel #" + d.ID + "\n\n")
	b.WriteString("- Challenger: `" + d.Challenger.String() + "` called **" + d.Call + "**\n")
	b.WriteString("- Opponent: `" + d.Opponent.String() + "`\n")
	b.WriteString("- Status: " + d.Status.String() + "\n")

	if d.Status == statusResolved {
		b.WriteString("- Coin landed on: **" + d.Result + "**\n")
		b.WriteString("- Winner: `" + d.Winner.String() + "`\n")
	}
	return b.String()
}

func renderPlayer(rawAddr string) string {
	addr := strings.TrimSpace(rawAddr)
	safe := escapeInline(addr)

	v := players.Get(addr)
	if v == nil {
		return "# Player " + safe + "\n\nNo recorded duels yet.\n"
	}
	ps := v.(*playerState)

	var b strings.Builder
	b.WriteString("# Player " + safe + "\n\n")
	b.WriteString("- Wins: " + strconv.Itoa(ps.Wins) + "\n")
	b.WriteString("- Losses: " + strconv.Itoa(ps.Losses) + "\n")
	b.WriteString("- Duels played: " + strconv.Itoa(ps.Duels) + "\n")
	return b.String()
}

// Render shows the duel arena at "", a specific duel when path is a numeric
// ID, or one player's record when path is their bech32 address.
func Render(path string) string {
	path = strings.TrimPrefix(strings.TrimSpace(path), "/")
	if path == "" {
		return renderHome()
	}
	if _, err := strconv.Atoi(path); err == nil {
		return renderDuel(path)
	}
	return renderPlayer(path)
}

package collatz

import (
	"chain"
	"chain/runtime/unsafe"
	"sort"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// maxIters caps the Collatz walk so a hostile / huge input cannot loop
// forever on-chain. No known n stays below this bound and fails to reach 1.
const maxIters = 1000000

// maxSeqLen caps how many terms Render("/<n>") will print.
const maxSeqLen = 500

// Result is one recorded submission.
type Result struct {
	N     int64
	Steps int
	Peak  int64
	Who   address
}

// results maps a decimal-string key of N -> Result. avl.Tree keeps a
// deterministic order for iteration inside Render.
var results avl.Tree

// stopping returns the number of steps to reach 1 and the peak value seen,
// walking the Collatz (hailstone) map. It never mutates state.
func stopping(n int64) (steps int, peak int64) {
	peak = n
	cur := n
	for cur != 1 {
		if steps >= maxIters {
			break
		}
		if cur%2 == 0 {
			cur = cur / 2
		} else {
			cur = 3*cur + 1
		}
		if cur > peak {
			peak = cur
		}
		steps++
	}
	return steps, peak
}

// Compute walks the hailstone sequence for n and records the result
// attributed to the caller. It is a crossing (state-mutating) func.
func Compute(cur realm, n int) {
	if n <= 0 {
		panic("n must be > 0")
	}
	caller := unsafe.PreviousRealm().Address()
	nn := int64(n)
	steps, peak := stopping(nn)

	res := Result{N: nn, Steps: steps, Peak: peak, Who: caller}
	key := strconv.FormatInt(nn, 10)
	results.Set(key, res)

	chain.Emit(
		"Computed",
		"n", key,
		"steps", strconv.Itoa(steps),
		"peak", strconv.FormatInt(peak, 10),
		"who", caller.String(),
	)
}

// byLongest implements sort.Interface, ordering results by steps desc,
// then peak desc, then n asc for stability.
type byLongest []Result

func (b byLongest) Len() int      { return len(b) }
func (b byLongest) Swap(i, j int) { b[i], b[j] = b[j], b[i] }
func (b byLongest) Less(i, j int) bool {
	if b[i].Steps != b[j].Steps {
		return b[i].Steps > b[j].Steps
	}
	if b[i].Peak != b[j].Peak {
		return b[i].Peak > b[j].Peak
	}
	return b[i].N < b[j].N
}

// Render shows the leaderboard at root, or the full hailstone sequence for a
// given n at path "/<n>".
func Render(path string) string {
	p := strings.TrimPrefix(path, "/")
	if p == "" {
		return renderLeaderboard()
	}
	return renderSequence(p)
}

func renderLeaderboard() string {
	all := make([]Result, 0, results.Size())
	results.Iterate("", "", func(_ string, v interface{}) bool {
		all = append(all, v.(Result))
		return false
	})

	var sb strings.Builder
	sb.WriteString("# Collatz Explorer\n\n")
	sb.WriteString("Hailstone-sequence explorer. Call `Compute(n)` to record a run, ")
	sb.WriteString("or view a full sequence at `/<n>`.\n\n")

	if len(all) == 0 {
		sb.WriteString("_No sequences submitted yet._\n")
		return sb.String()
	}

	sort.Stable(byLongest(all))

	sb.WriteString("## Leaderboard — longest sequences\n\n")
	sb.WriteString("| # | n | steps | peak | who |\n")
	sb.WriteString("|---|---|-------|------|-----|\n")
	limit := len(all)
	if limit > 20 {
		limit = 20
	}
	for i := 0; i < limit; i++ {
		r := all[i]
		sb.WriteString("| " + strconv.Itoa(i+1) + " | ")
		sb.WriteString("[" + strconv.FormatInt(r.N, 10) + "](/r:" + strconv.FormatInt(r.N, 10) + ") | ")
		sb.WriteString(strconv.Itoa(r.Steps) + " | ")
		sb.WriteString(strconv.FormatInt(r.Peak, 10) + " | ")
		sb.WriteString(r.Who.String() + " |\n")
	}
	sb.WriteString("\n_" + strconv.Itoa(len(all)) + " sequence(s) recorded._\n")
	return sb.String()
}

func renderSequence(p string) string {
	n, err := strconv.ParseInt(p, 10, 64)
	var sb strings.Builder
	if err != nil || n <= 0 {
		sb.WriteString("# Invalid n\n\n`" + p + "` is not a positive integer.\n")
		return sb.String()
	}

	sb.WriteString("# Hailstone sequence for " + strconv.FormatInt(n, 10) + "\n\n")

	seq := make([]int64, 0, 64)
	cur := n
	var peak int64 = n
	truncated := false
	for {
		seq = append(seq, cur)
		if cur == 1 {
			break
		}
		if len(seq) >= maxSeqLen {
			truncated = true
			break
		}
		if cur%2 == 0 {
			cur = cur / 2
		} else {
			cur = 3*cur + 1
		}
		if cur > peak {
			peak = cur
		}
	}

	parts := make([]string, len(seq))
	for i, v := range seq {
		parts[i] = strconv.FormatInt(v, 10)
	}
	sb.WriteString(strings.Join(parts, " → "))
	sb.WriteString("\n\n")
	sb.WriteString("- steps: " + strconv.Itoa(len(seq)-1) + "\n")
	sb.WriteString("- peak: " + strconv.FormatInt(peak, 10) + "\n")
	if truncated {
		sb.WriteString("\n_Sequence truncated at " + strconv.Itoa(maxSeqLen) + " terms._\n")
	}
	return sb.String()
}

package connect4

import (
	"chain"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	cols = 7
	rows = 6
)

// cell values
const (
	empty = 0
	red   = 1 // 🔴 game creator (caller of NewGame)
	yel   = 2 // 🟡 opponent
)

// Game holds the full state of one Connect Four match.
// board is indexed board[row][col]; row 0 is the BOTTOM row.
type Game struct {
	ID       int64
	Red      address // 🔴 creator, moves first
	Yellow   address // 🟡 opponent
	Board    [rows][cols]int
	Turn     int  // whose turn: red or yel
	Winner   int  // empty until decided; red/yel = winner
	Draw     bool // true when board full with no winner
	Finished bool
}

var (
	games  = avl.NewTree() // id (zero-padded string) -> *Game
	nextID int64
)

func idKey(id int64) string {
	// zero-pad so avl iteration order matches numeric order for Render lists
	s := strconv.FormatInt(id, 10)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

// NewGame creates a match between the caller (🔴) and opponent (🟡).
// Returns the new game id.
func NewGame(cur realm, opponent address) int64 {
	caller := unsafe.PreviousRealm().Address()
	if opponent == caller {
		panic("opponent must differ from caller")
	}
	if opponent.String() == "" {
		panic("opponent address is empty")
	}
	nextID++
	g := &Game{
		ID:     nextID,
		Red:    caller,
		Yellow: opponent,
		Turn:   red,
	}
	games.Set(idKey(g.ID), g)
	chain.Emit("GameCreated",
		"id", strconv.FormatInt(g.ID, 10),
		"red", caller.String(),
		"yellow", opponent.String(),
	)
	return g.ID
}

func getGame(id int64) (*Game, error) {
	v := games.Get(idKey(id))
	if v == nil {
		return nil, errors.New("game not found: " + strconv.FormatInt(id, 10))
	}
	return v.(*Game), nil
}

// Drop places the caller's disc into the given column (0-6).
// Enforces turn order by caller, rejects full columns, and detects
// a 4-in-a-row win or a draw.
func Drop(cur realm, gameID int64, column int) {
	if column < 0 || column >= cols {
		panic("column out of range (0-6)")
	}
	g, err := getGame(gameID)
	if err != nil {
		panic(err.Error())
	}
	if g.Finished {
		panic("game already finished")
	}

	caller := unsafe.PreviousRealm().Address()
	var mover int
	switch caller {
	case g.Red:
		mover = red
	case g.Yellow:
		mover = yel
	default:
		panic("caller is not a player in this game")
	}
	if mover != g.Turn {
		panic("not your turn")
	}

	// find lowest empty row in the column
	placed := -1
	for r := 0; r < rows; r++ {
		if g.Board[r][column] == empty {
			g.Board[r][column] = mover
			placed = r
			break
		}
	}
	if placed == -1 {
		panic("column is full")
	}

	if wins(&g.Board, placed, column, mover) {
		g.Winner = mover
		g.Finished = true
		chain.Emit("GameWon",
			"id", strconv.FormatInt(g.ID, 10),
			"winner", caller.String(),
		)
	} else if full(&g.Board) {
		g.Draw = true
		g.Finished = true
		chain.Emit("GameDraw", "id", strconv.FormatInt(g.ID, 10))
	} else {
		if g.Turn == red {
			g.Turn = yel
		} else {
			g.Turn = red
		}
		chain.Emit("DiscDropped",
			"id", strconv.FormatInt(g.ID, 10),
			"col", strconv.Itoa(column),
			"player", caller.String(),
		)
	}

	games.Set(idKey(g.ID), g)
}

func full(b *[rows][cols]int) bool {
	for c := 0; c < cols; c++ {
		if b[rows-1][c] == empty {
			return false
		}
	}
	return true
}

// wins checks whether the disc just placed at (r,c) for player p completes
// a run of 4 in any of the four directions.
func wins(b *[rows][cols]int, r, c, p int) bool {
	// direction pairs: horizontal, vertical, diag /, diag \
	dirs := [4][2]int{{0, 1}, {1, 0}, {1, 1}, {1, -1}}
	for _, d := range dirs {
		count := 1
		count += run(b, r, c, d[0], d[1], p)
		count += run(b, r, c, -d[0], -d[1], p)
		if count >= 4 {
			return true
		}
	}
	return false
}

func run(b *[rows][cols]int, r, c, dr, dc, p int) int {
	n := 0
	for i := 1; i < 4; i++ {
		rr := r + dr*i
		cc := c + dc*i
		if rr < 0 || rr >= rows || cc < 0 || cc >= cols {
			break
		}
		if b[rr][cc] != p {
			break
		}
		n++
	}
	return n
}

func glyph(v int) string {
	switch v {
	case red:
		return "🔴"
	case yel:
		return "🟡"
	default:
		return "·"
	}
}

// Render draws the board with 🔴🟡· and shows whose turn / the winner.
// path "" lists all games; path "<id>" shows a single board.
func Render(path string) string {
	path = strings.TrimSpace(strings.Trim(path, "/"))
	if path == "" {
		return renderList()
	}
	id, err := strconv.ParseInt(path, 10, 64)
	if err != nil {
		return "# Connect Four\n\nInvalid game id: `" + path + "`\n"
	}
	g, err := getGame(id)
	if err != nil {
		return "# Connect Four\n\n" + err.Error() + "\n"
	}
	return renderGame(g)
}

func renderList() string {
	var sb strings.Builder
	sb.WriteString("# Connect Four\n\n")
	sb.WriteString("Two-player Connect Four on a 7×6 board. 🔴 is the game creator, 🟡 the opponent.\n\n")
	if games.Size() == 0 {
		sb.WriteString("_No games yet. Call `NewGame(opponent)` to start one._\n")
		return sb.String()
	}
	sb.WriteString("## Games\n\n")
	sb.WriteString("| ID | 🔴 Red | 🟡 Yellow | Status |\n")
	sb.WriteString("|----|--------|-----------|--------|\n")
	games.Iterate("", "", func(_ string, v any) bool {
		g := v.(*Game)
		status := ""
		switch {
		case g.Winner == red:
			status = "🔴 won"
		case g.Winner == yel:
			status = "🟡 won"
		case g.Draw:
			status = "draw"
		case g.Turn == red:
			status = "🔴 to move"
		default:
			status = "🟡 to move"
		}
		sb.WriteString("| [" + strconv.FormatInt(g.ID, 10) + "](/r:" + strconv.FormatInt(g.ID, 10) + ") | " +
			short(g.Red) + " | " + short(g.Yellow) + " | " + status + " |\n")
		return false
	})
	sb.WriteString("\nOpen a game by its id (e.g. path `1`).\n")
	return sb.String()
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return "`" + s + "`"
	}
	return "`" + s[:8] + "…" + s[len(s)-4:] + "`"
}

func renderGame(g *Game) string {
	var sb strings.Builder
	sb.WriteString("# Connect Four — Game " + strconv.FormatInt(g.ID, 10) + "\n\n")
	sb.WriteString("- 🔴 Red: `" + g.Red.String() + "`\n")
	sb.WriteString("- 🟡 Yellow: `" + g.Yellow.String() + "`\n\n")

	// status line
	switch {
	case g.Winner == red:
		sb.WriteString("**🔴 Red wins!**\n\n")
	case g.Winner == yel:
		sb.WriteString("**🟡 Yellow wins!**\n\n")
	case g.Draw:
		sb.WriteString("**Draw — board full.**\n\n")
	case g.Turn == red:
		sb.WriteString("**Turn: 🔴 Red**\n\n")
	default:
		sb.WriteString("**Turn: 🟡 Yellow**\n\n")
	}

	// board top-down (row rows-1 at top, row 0 at bottom)
	sb.WriteString("```\n")
	for r := rows - 1; r >= 0; r-- {
		for c := 0; c < cols; c++ {
			sb.WriteString(glyph(g.Board[r][c]))
		}
		sb.WriteString("\n")
	}
	// column indices
	for c := 0; c < cols; c++ {
		sb.WriteString(strconv.Itoa(c))
	}
	sb.WriteString("\n```\n\n")

	if !g.Finished {
		sb.WriteString("Drop a disc: `Drop(" + strconv.FormatInt(g.ID, 10) + ", <col 0-6>)`\n")
	}
	return sb.String()
}

// Package counter implements "Counter Club": a single shared integer counter
// with a rolling history of the last 20 mutations. Anyone may Inc, Dec, or
// Reset the value; every change records the caller, the delta applied, the
// resulting value, and the block height it happened at.
package counter

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"strings"
)

// maxHistory is the number of recent changes kept in the log.
const maxHistory = 20

// change is a single recorded mutation of the counter.
type change struct {
	caller address // who triggered the change
	delta  int     // how much the value moved (+1, -1, or reset amount)
	value  int     // the resulting counter value after the change
	height int64   // block height at which it occurred
}

// value is the current shared counter.
var value int

// total counts every mutation ever applied (not capped, unlike history).
var total int

// history holds the last maxHistory changes, oldest first.
var history []change

// record appends a change to the history, trimming to the last maxHistory.
func record(delta, newValue int) {
	c := change{
		caller: unsafe.PreviousRealm().Address(),
		delta:  delta,
		value:  newValue,
		height: runtime.ChainHeight(),
	}
	history = append(history, c)
	if len(history) > maxHistory {
		history = history[len(history)-maxHistory:]
	}
	total++
	chain.Emit(
		"CounterChange",
		"delta", strconv.Itoa(delta),
		"value", strconv.Itoa(newValue),
	)
}

// Inc adds one to the shared counter and logs the change.
func Inc(cur realm) int {
	value++
	record(1, value)
	return value
}

// Dec subtracts one from the shared counter and logs the change.
func Dec(cur realm) int {
	value--
	record(-1, value)
	return value
}

// Reset sets the shared counter back to zero and logs the change. The recorded
// delta is the amount required to bring the previous value to zero.
func Reset(cur realm) int {
	delta := -value
	value = 0
	record(delta, value)
	return value
}

// Value returns the current counter value (read-only helper).
func Value() int {
	return value
}

// Total returns the total number of mutations ever applied.
func Total() int {
	return total
}

// Render produces a Markdown view: the big current value, the total number of
// changes, and a table of the most recent changes (newest first).
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Counter Club\n\n")
	b.WriteString("A shared counter anyone can Inc, Dec, or Reset. ")
	b.WriteString("The last ")
	b.WriteString(strconv.Itoa(maxHistory))
	b.WriteString(" changes are logged below.\n\n")

	// Big current value.
	b.WriteString("## Current value\n\n")
	b.WriteString("# ")
	b.WriteString(strconv.Itoa(value))
	b.WriteString("\n\n")

	b.WriteString("**Total changes:** ")
	b.WriteString(strconv.Itoa(total))
	b.WriteString("\n\n")

	// Recent history, newest first.
	b.WriteString("## Recent history\n\n")
	if len(history) == 0 {
		b.WriteString("_No changes yet — be the first to count!_\n")
		return b.String()
	}

	b.WriteString("| # | Caller | Delta | New value | Height |\n")
	b.WriteString("|---|--------|-------|-----------|--------|\n")
	n := len(history)
	for i := n - 1; i >= 0; i-- {
		c := history[i]
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(n - i))
		b.WriteString(" | ")
		b.WriteString(c.caller.String())
		b.WriteString(" | ")
		b.WriteString(signed(c.delta))
		b.WriteString(" | ")
		b.WriteString(strconv.Itoa(c.value))
		b.WriteString(" | ")
		b.WriteString(strconv.FormatInt(c.height, 10))
		b.WriteString(" |\n")
	}

	return b.String()
}

// signed formats an int with an explicit leading sign for non-negative values.
func signed(n int) string {
	if n >= 0 {
		return "+" + strconv.Itoa(n)
	}
	return strconv.Itoa(n)
}

// Package dice implements a provably-fair on-chain dice game for gno.land.
//
// There is no true randomness on-chain: every node must reach the same result
// deterministically. Instead, each roll derives its 1-6 face from public block
// entropy (chain height) mixed with the caller address and the caller's roll
// count. The derivation is fully reproducible from public data, which is what
// "provably fair" means here — anyone can recompute a roll and verify it.
package dice

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// history holds every roll made by a single caller, most recent last.
type history struct {
	rolls []int // each value in [1,6]
}

var (
	// count[i] is the total number of times face (i+1) has come up globally.
	count [6]int
	// total is the total number of rolls across all callers.
	total int
	// players maps caller address string -> *history (deterministic iteration).
	players = avl.NewTree()
)

// deriveFace turns public entropy into a face in [1,6]. It is deterministic:
// the same (height, addr, n) always yields the same face, so any observer can
// recompute and verify a roll. Uses a simple FNV-1a-style hash over the mixed
// entropy bytes so different callers at the same height get different faces.
func deriveFace(height int64, addr string, n int) int {
	const (
		offset = uint64(1469598103934665603)
		prime  = uint64(1099511628211)
	)
	h := offset
	mix := func(v uint64) {
		for i := 0; i < 8; i++ {
			h ^= v & 0xff
			h *= prime
			v >>= 8
		}
	}
	mix(uint64(height))
	mix(uint64(n))
	for i := 0; i < len(addr); i++ {
		h ^= uint64(addr[i])
		h *= prime
	}
	return int(h%6) + 1
}

// Roll performs one dice roll for the calling account and records it.
//
// It is a crossing function (gno 0.9 interrealm convention: `cur realm` first
// parameter). Callers invoke it as Roll(cross(cur)). The result is derived
// deterministically from the current block height, the caller address, and the
// caller's prior roll count — no stored secret, fully verifiable.
func Roll(cur realm) int {
	if !cur.IsCurrent() {
		panic("dice: spoofed realm value")
	}
	addr := cur.Previous().Address().String()

	var h *history
	if v := players.Get(addr); v != nil {
		h = v.(*history)
	} else {
		h = &history{}
		players.Set(addr, h)
	}

	face := deriveFace(runtime.ChainHeight(), addr, len(h.rolls))
	h.rolls = append(h.rolls, face)
	count[face-1]++
	total++

	chain.Emit("Roll", "player", addr, "face", strconv.Itoa(face))
	return face
}

// RollsOf returns the recorded roll history for an address (oldest first).
// Read-only helper, safe to call as a query.
func RollsOf(addr string) []int {
	v := players.Get(addr)
	if v == nil {
		return nil
	}
	out := v.(*history).rolls
	cp := make([]int, len(out))
	copy(cp, out)
	return cp
}

// Total returns the global roll count.
func Total() int { return total }

// Distribution returns the global per-face counts, faces 1-6.
func Distribution() [6]int { return count }

// bar renders a proportional ▓/░ bar of fixed width for a face's share.
func bar(n, max, width int) string {
	if max <= 0 {
		return strings.Repeat("░", width)
	}
	filled := n * width / max
	if filled > width {
		filled = width
	}
	return strings.Repeat("▓", filled) + strings.Repeat("░", width-filled)
}

// Render returns the realm's gnoweb Markdown view.
//
// Render is NOT a crossing function (no `cur realm` param) — it is a read-only
// query surface. It shows the total roll count, a distribution bar chart for
// faces 1-6, and the most recent rolls.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# 🎲 Provably-Fair Dice\n\n")
	b.WriteString("Every roll is derived deterministically from the block height, ")
	b.WriteString("the caller address, and their roll count — no hidden randomness, ")
	b.WriteString("fully reproducible from public data.\n\n")

	b.WriteString("**Total rolls:** " + strconv.Itoa(total) + "\n\n")

	// Distribution bar chart.
	b.WriteString("## Distribution\n\n")
	max := 0
	for _, c := range count {
		if c > max {
			max = c
		}
	}
	for face := 1; face <= 6; face++ {
		c := count[face-1]
		pct := 0
		if total > 0 {
			pct = c * 100 / total
		}
		b.WriteString("`" + strconv.Itoa(face) + "` ")
		b.WriteString(bar(c, max, 20))
		b.WriteString(" " + strconv.Itoa(c))
		b.WriteString(" (" + strconv.Itoa(pct) + "%)\n\n")
	}

	// Recent rolls: walk players, collect last rolls, show most recent globally.
	b.WriteString("## Recent rolls\n\n")
	if total == 0 {
		b.WriteString("_No rolls yet. Call `Roll` to play._\n")
		return b.String()
	}
	type entry struct {
		addr string
		face int
	}
	recent := []entry{}
	players.Iterate("", "", func(key string, value interface{}) bool {
		h := value.(*history)
		// take up to the last 3 rolls of each player
		start := len(h.rolls) - 3
		if start < 0 {
			start = 0
		}
		for _, f := range h.rolls[start:] {
			recent = append(recent, entry{addr: key, face: f})
		}
		return false
	})
	// show at most the last 10 collected
	start := len(recent) - 10
	if start < 0 {
		start = 0
	}
	for _, e := range recent[start:] {
		short := e.addr
		if len(short) > 12 {
			short = short[:8] + "…" + short[len(short)-4:]
		}
		b.WriteString("- 🎲 **" + strconv.Itoa(e.face) + "** — `" + short + "`\n")
	}
	return b.String()
}

// Package dutchauction ports the classic Solidity Dutch-auction pattern to
// gno.land: a seller lists an item at a high starting price that decays
// linearly, block by block, down to a floor price. The first buyer to call
// Buy pays whatever the price is at that moment — real ugnot, escrowed by
// the chain with the transaction and forwarded to the seller on settlement.
// Overpayment is refunded automatically. State-mutating functions are
// crossing functions (`cur realm`) per the gno 0.9 interrealm convention.
package dutchauction

import (
	"errors"
	"strconv"
	"strings"

	"chain"
	"chain/banker"
	"chain/runtime"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

const denom = "ugnot"

type status int

const (
	statusActive status = iota
	statusSold
	statusCancelled
)

func (s status) String() string {
	switch s {
	case statusActive:
		return "active"
	case statusSold:
		return "sold"
	case statusCancelled:
		return "cancelled"
	default:
		return "unknown"
	}
}

// auction is one listing: price falls linearly from StartPrice to
// FloorPrice over Duration blocks starting at StartHeight, then holds flat
// at FloorPrice until bought or cancelled.
type auction struct {
	ID          string
	Item        string
	Seller      address
	StartPrice  int64
	FloorPrice  int64
	StartHeight int64
	Duration    int64
	Status      status
	Buyer       address
	SoldPrice   int64
}

var (
	auctions    avl.Tree // id string -> *auction
	nextID      uint64
	totalListed uint64
	totalSold   uint64
	totalVolume int64
)

var (
	errEmptyItem    = errors.New("dutchauction: item description required")
	errBadPrice     = errors.New("dutchauction: startPrice must be greater than floorPrice, floorPrice must be >= 0")
	errBadDuration  = errors.New("dutchauction: durationBlocks must be positive")
	errNotFound     = errors.New("dutchauction: auction not found")
	errNotActive    = errors.New("dutchauction: auction is not active")
	errNotSeller    = errors.New("dutchauction: caller is not the seller")
	errNotUserCall  = errors.New("dutchauction: buy must be a direct user transaction")
	errUnderpaid    = errors.New("dutchauction: payment below current price")
	errSpoofedRealm = errors.New("dutchauction: spoofed realm")
)

// caller authenticates the crossing frame and returns the immediate caller.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic(errSpoofedRealm)
	}
	return cur.Previous().Address()
}

// List creates a new Dutch auction for item, starting at startPrice ugnot
// and falling linearly to floorPrice over durationBlocks. Returns the new
// auction's ID. Crossing function.
func List(cur realm, item string, startPrice, floorPrice, durationBlocks int64) string {
	seller := caller(cur)

	item = strings.TrimSpace(item)
	if item == "" {
		panic(errEmptyItem)
	}
	if floorPrice < 0 || startPrice <= floorPrice {
		panic(errBadPrice)
	}
	if durationBlocks <= 0 {
		panic(errBadDuration)
	}

	nextID++
	id := strconv.FormatUint(nextID, 10)
	auctions.Set(id, &auction{
		ID:          id,
		Item:        item,
		Seller:      seller,
		StartPrice:  startPrice,
		FloorPrice:  floorPrice,
		StartHeight: runtime.ChainHeight(),
		Duration:    durationBlocks,
		Status:      statusActive,
	})
	totalListed++
	return id
}

// Buy purchases auction id at its current price. The caller must send at
// least that many ugnot with the transaction; any excess is refunded
// immediately. Only a direct EOA transaction (MsgCall) may buy, so the
// payment envelope can't be spoofed via an ephemeral MsgRun realm. Returns
// the price actually paid. Crossing function.
func Buy(cur realm, id string) int64 {
	if !cur.Previous().IsUserCall() {
		panic(errNotUserCall)
	}
	buyer := cur.Previous().Address()

	a := getAuction(id)
	if a.Status != statusActive {
		panic(errNotActive)
	}

	price := priceAt(a, runtime.ChainHeight())
	sent := unsafe.OriginSend()
	paid := sent.AmountOf(denom)
	if paid < price {
		panic(errUnderpaid)
	}

	a.Status = statusSold
	a.Buyer = buyer
	a.SoldPrice = price
	totalSold++
	totalVolume += price

	bnk := banker.NewBanker(banker.BankerTypeOriginSend, cur)
	pkgAddr := cur.Address()
	if paid > price {
		bnk.SendCoins(pkgAddr, buyer, chain.NewCoins(chain.NewCoin(denom, paid-price)))
	}
	bnk.SendCoins(pkgAddr, a.Seller, chain.NewCoins(chain.NewCoin(denom, price)))

	return price
}

// Cancel withdraws an active auction. Only the seller may cancel, and only
// before it's bought. Crossing function.
func Cancel(cur realm, id string) {
	who := caller(cur)

	a := getAuction(id)
	if a.Status != statusActive {
		panic(errNotActive)
	}
	if who != a.Seller {
		panic(errNotSeller)
	}
	a.Status = statusCancelled
}

// CurrentPrice returns id's price at the current chain height.
func CurrentPrice(id string) int64 {
	return priceAt(getAuction(id), runtime.ChainHeight())
}

// AuctionInfo returns a snapshot of auction id.
func AuctionInfo(id string) (item string, seller address, status string, currentPrice int64, floorPrice int64, startPrice int64) {
	a := getAuction(id)
	return a.Item, a.Seller, a.Status.String(), priceAt(a, runtime.ChainHeight()), a.FloorPrice, a.StartPrice
}

// priceAt computes the linear-decay price of a at the given height. Once
// settled (sold or cancelled), the price is frozen: SoldPrice for a sale,
// zero for a cancellation.
func priceAt(a *auction, height int64) int64 {
	if a.Status != statusActive {
		return a.SoldPrice
	}
	elapsed := height - a.StartHeight
	if elapsed <= 0 {
		return a.StartPrice
	}
	if elapsed >= a.Duration {
		return a.FloorPrice
	}
	drop := a.StartPrice - a.FloorPrice
	return a.StartPrice - drop*elapsed/a.Duration
}

func getAuction(id string) *auction {
	v := auctions.Get(id)
	if v == nil {
		panic(errNotFound)
	}
	return v.(*auction)
}

// Render produces the gnoweb Markdown view: a table of every auction,
// newest first, with live prices. Not a crossing function.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Dutch Auction\n\n")
	b.WriteString("A price that only ever falls. List an item high; it decays block by ")
	b.WriteString("block toward a floor; the first `Buy` call wins it at whatever the ")
	b.WriteString("price is at that instant. Real ugnot, escrowed by the chain and paid ")
	b.WriteString("straight to the seller — overpayment is refunded automatically.\n\n")

	b.WriteString("- **Total listed:** " + strconv.FormatUint(totalListed, 10) + "\n")
	b.WriteString("- **Total sold:** " + strconv.FormatUint(totalSold, 10) + "\n")
	b.WriteString("- **Total volume:** " + strconv.FormatInt(totalVolume, 10) + " ugnot\n")
	b.WriteString("- **Current height:** " + strconv.FormatInt(runtime.ChainHeight(), 10) + "\n\n")

	if auctions.Size() == 0 {
		b.WriteString("_No auctions yet — call `List` to open one._\n")
		return b.String()
	}

	b.WriteString("## Auctions\n\n")
	b.WriteString("| ID | Item | Status | Price now | Floor | Start | Seller |\n")
	b.WriteString("| ---: | --- | --- | ---: | ---: | ---: | --- |\n")

	height := runtime.ChainHeight()
	ids := make([]uint64, 0, auctions.Size())
	auctions.Iterate("", "", func(key string, value any) bool {
		n, _ := strconv.ParseUint(key, 10, 64)
		ids = append(ids, n)
		return false
	})
	for i := len(ids) - 1; i >= 0; i-- {
		id := strconv.FormatUint(ids[i], 10)
		v := auctions.Get(id)
		a := v.(*auction)
		b.WriteString("| " + a.ID + " | " + a.Item + " | " + a.Status.String() +
			" | " + strconv.FormatInt(priceAt(a, height), 10) +
			" | " + strconv.FormatInt(a.FloorPrice, 10) +
			" | " + strconv.FormatInt(a.StartPrice, 10) +
			" | `" + a.Seller.String() + "` |\n")
	}

	return b.String()
}

// Package eggling is an on-chain egg incubator and creature collector.
// Plant an egg, let it incubate for a minimum number of blocks, then Hatch
// it: the longer you waited (and a little luck, seeded from the egg's own
// history) decides the rarity of the creature you get. Train hatched
// creatures to level them up. Unlike a tamagotchi there's nothing to feed
// or lose to neglect — eggling is about patience and the luck of the
// hatch, not survival.
package eggling

import (
	"crypto/sha256"
	"encoding/hex"
	"sort"
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// minIncubation is the minimum number of blocks an egg must sit before it
// can hatch.
const minIncubation int64 = 20

// waitCap is the incubation-time bonus cap (in blocks) used by rarityTier,
// so waiting forever doesn't guarantee a legendary — it just improves odds.
const waitCap int64 = 200

var speciesNames = [...]string{
	"Slime", "Sprout", "Ember", "Pebble", "Breeze", "Glimmer", "Shade", "Coral",
}

var rarityNames = [...]string{"Common", "Uncommon", "Rare", "Legendary"}
var rarityEmoji = [...]string{"⚪", "🟢", "🔵", "🟡"}

// egg is the persisted record for one planted egg, hatched or not.
type egg struct {
	ID         string
	Owner      address
	PlantedAt  int64
	Hatched    bool
	Species    string
	RarityTier int
	Name       string
	XP         int
	Level      int
}

var (
	eggs         avl.Tree // id string -> *egg
	nextID       int
	totalPlanted int
	totalHatched int
	rarityCounts [4]int
)

func get(id string) (*egg, bool) {
	v := eggs.Get(id)
	if v == nil {
		return nil, false
	}
	return v.(*egg), true
}

// hashSeed hashes the given parts (joined with ":") to a deterministic hex
// digest. Used to derive an egg's species and rarity roll from facts
// already fixed at plant time, so nobody — not even the owner — can game
// the outcome after the fact.
func hashSeed(parts ...string) string {
	sum := sha256.Sum256([]byte(strings.Join(parts, ":")))
	return hex.EncodeToString(sum[:])
}

// seedBytes pulls the first two bytes out of a hex digest for use as two
// independent 0-255 rolls (species pick, rarity roll).
func seedBytes(seedHex string) (byte, byte) {
	raw, err := hex.DecodeString(seedHex)
	if err != nil || len(raw) < 2 {
		return 0, 0
	}
	return raw[0], raw[1]
}

// rarityTier turns a 0-255 roll plus the blocks waited into a tier index
// 0..3 (common..legendary). Waiting longer raises the effective score, so
// patience improves your odds, but a bad roll can still land common even
// after a long wait, and a lucky roll can hatch rare almost immediately.
func rarityTier(roll uint8, waitBlocks int64) int {
	bonus := waitBlocks
	if bonus > waitCap {
		bonus = waitCap
	}
	score := int(roll) + int(bonus)/2
	switch {
	case score >= 300:
		return 3
	case score >= 220:
		return 2
	case score >= 140:
		return 1
	default:
		return 0
	}
}

// plant is the non-crossing core of PlantEgg.
func plant(owner address, height int64) *egg {
	nextID++
	id := strconv.Itoa(nextID)
	e := &egg{ID: id, Owner: owner, PlantedAt: height}
	eggs.Set(id, e)
	totalPlanted++
	return e
}

// PlantEgg starts incubating a new egg for the caller. Returns its ID.
func PlantEgg(cur realm) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	e := plant(cur.Previous().Address(), runtime.ChainHeight())
	return "🥚 planted egg #" + e.ID + " — incubate at least " +
		strconv.Itoa(int(minIncubation)) + " blocks, then Hatch(\"" + e.ID + "\")"
}

// hatch is the non-crossing core of Hatch.
func hatch(e *egg, height int64) string {
	if e.Hatched {
		panic("egg #" + e.ID + " already hatched into a " + e.Species)
	}
	wait := height - e.PlantedAt
	if wait < minIncubation {
		panic("egg #" + e.ID + " needs " + strconv.Itoa(int(minIncubation-wait)) + " more blocks to incubate")
	}

	seed := hashSeed(e.ID, e.Owner.String(), strconv.FormatInt(e.PlantedAt, 10))
	rarityRoll, speciesRoll := seedBytes(seed)
	tier := rarityTier(rarityRoll, wait)
	species := speciesNames[int(speciesRoll)%len(speciesNames)]

	e.Hatched = true
	e.Species = species
	e.RarityTier = tier
	e.Name = species
	e.Level = 1
	rarityCounts[tier]++
	totalHatched++

	return rarityEmoji[tier] + " egg #" + e.ID + " hatched into a " + rarityNames[tier] + " " + species + "!"
}

// Hatch hatches an incubated egg the caller owns.
func Hatch(cur realm, id string) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	e, ok := get(id)
	if !ok {
		panic("no such egg #" + id)
	}
	if e.Owner != cur.Previous().Address() {
		panic("only the owner can hatch egg #" + id)
	}
	return hatch(e, runtime.ChainHeight())
}

// train is the non-crossing core of Train.
func train(e *egg) string {
	if !e.Hatched {
		panic("egg #" + e.ID + " hasn't hatched yet")
	}
	e.XP += 10
	newLevel := e.XP/50 + 1
	leveled := newLevel > e.Level
	e.Level = newLevel

	msg := e.Name + " gained 10 XP (" + strconv.Itoa(e.XP) + " total)"
	if leveled {
		msg += " and reached level " + strconv.Itoa(e.Level) + "!"
	}
	return msg
}

// Train gives a hatched creature the caller owns some experience, leveling
// it up every 50 XP.
func Train(cur realm, id string) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	e, ok := get(id)
	if !ok {
		panic("no such egg #" + id)
	}
	if e.Owner != cur.Previous().Address() {
		panic("only the owner can train egg #" + id)
	}
	return train(e)
}

// rename is the non-crossing core of Rename.
func rename(e *egg, name string) string {
	if !e.Hatched {
		panic("egg #" + e.ID + " hasn't hatched yet — nothing to name")
	}
	name = strings.TrimSpace(name)
	if name == "" {
		panic("name cannot be empty")
	}
	old := e.Name
	e.Name = name
	return old + " renamed to " + name
}

// Rename gives a hatched creature the caller owns a custom name.
func Rename(cur realm, id string, name string) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	e, ok := get(id)
	if !ok {
		panic("no such egg #" + id)
	}
	if e.Owner != cur.Previous().Address() {
		panic("only the owner can rename egg #" + id)
	}
	return rename(e, name)
}

// escapeInline neutralizes markdown-active characters in untrusted text
// before it's embedded inline in Render output.
func escapeInline(s string) string {
	r := strings.NewReplacer(
		"\\", "\\\\",
		"`", "\\`",
		"*", "\\*",
		"_", "\\_",
		"[", "\\[",
		"]", "\\]",
		"|", "\\|",
	)
	return r.Replace(s)
}

func shortAddr(a address) string {
	s := a.String()
	if len(s) > 12 {
		return s[:8] + "…" + s[len(s)-4:]
	}
	return s
}

// byIDNumeric orders eggs by their numeric ID, ascending.
type byIDNumeric []*egg

func (r byIDNumeric) Len() int      { return len(r) }
func (r byIDNumeric) Swap(i, j int) { r[i], r[j] = r[j], r[i] }
func (r byIDNumeric) Less(i, j int) bool {
	a, _ := strconv.Atoi(r[i].ID)
	b, _ := strconv.Atoi(r[j].ID)
	return a < b
}

func allEggs() []*egg {
	var rows []*egg
	eggs.Iterate("", "", func(_ string, v any) bool {
		rows = append(rows, v.(*egg))
		return false
	})
	sort.Stable(byIDNumeric(rows))
	return rows
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# 🥚 Eggling\n\n")
	b.WriteString("An on-chain egg incubator. `PlantEgg()` to start one, wait at least " +
		strconv.Itoa(int(minIncubation)) + " blocks, then `Hatch(id)` — the longer you " +
		"waited (plus a little sealed-in luck) decides the rarity of the creature you get. " +
		"`Train(id)` levels a hatched creature up; `Rename(id, name)` gives it a name.\n\n")

	b.WriteString("- Eggs planted: " + strconv.Itoa(totalPlanted) + "\n")
	b.WriteString("- Creatures hatched: " + strconv.Itoa(totalHatched) + "\n")
	if totalHatched > 0 {
		for tier := 3; tier >= 0; tier-- {
			if rarityCounts[tier] > 0 {
				b.WriteString("  - " + rarityEmoji[tier] + " " + rarityNames[tier] + ": " +
					strconv.Itoa(rarityCounts[tier]) + "\n")
			}
		}
	}

	rows := allEggs()
	b.WriteString("\n## Eggs\n\n")
	if len(rows) == 0 {
		b.WriteString("_None planted yet. Be the first!_\n")
		return b.String()
	}

	b.WriteString("| ID | Owner | Status | Level |\n")
	b.WriteString("| :--- | :--- | :--- | ---: |\n")
	for _, e := range rows {
		status := "🥚 incubating"
		level := "-"
		if e.Hatched {
			status = rarityEmoji[e.RarityTier] + " " + escapeInline(e.Name) + " (" + rarityNames[e.RarityTier] + " " + e.Species + ")"
			level = strconv.Itoa(e.Level)
		}
		b.WriteString("| #" + e.ID + " | `" + shortAddr(e.Owner) + "` | " + status + " | " + level + " |\n")
	}
	b.WriteString("\n_View a single egg at this realm's path plus its ID (e.g. `.../eggling:3`), " +
		"or one owner's eggs plus their address._\n")
	return b.String()
}

func renderEgg(id string, height int64) string {
	e, ok := get(id)
	if !ok {
		return "# Egg #" + escapeInline(id) + "\n\nNo such egg.\n"
	}

	var b strings.Builder
	if !e.Hatched {
		wait := height - e.PlantedAt
		b.WriteString("# 🥚 Egg #" + e.ID + "\n\n")
		b.WriteString("- Owner: `" + e.Owner.String() + "`\n")
		b.WriteString("- Planted at block: " + strconv.FormatInt(e.PlantedAt, 10) + "\n")
		if wait < minIncubation {
			b.WriteString("- Ready to hatch in: " + strconv.FormatInt(minIncubation-wait, 10) + " more blocks\n")
		} else {
			b.WriteString("- Ready to hatch now — call `Hatch(\"" + e.ID + "\")`\n")
		}
		return b.String()
	}

	b.WriteString("# " + rarityEmoji[e.RarityTier] + " " + e.Name + "\n\n")
	b.WriteString("- Owner: `" + e.Owner.String() + "`\n")
	b.WriteString("- Species: " + e.Species + "\n")
	b.WriteString("- Rarity: " + rarityNames[e.RarityTier] + "\n")
	b.WriteString("- Level: " + strconv.Itoa(e.Level) + " (" + strconv.Itoa(e.XP) + " XP)\n")
	return b.String()
}

func renderOwner(rawAddr string) string {
	owner := address(strings.TrimSpace(rawAddr))
	safe := escapeInline(owner.String())

	var b strings.Builder
	b.WriteString("# Eggs owned by " + safe + "\n\n")

	found := false
	for _, e := range allEggs() {
		if e.Owner != owner {
			continue
		}
		found = true
		if e.Hatched {
			b.WriteString("- #" + e.ID + ": " + rarityEmoji[e.RarityTier] + " " + escapeInline(e.Name) +
				" — " + rarityNames[e.RarityTier] + " " + e.Species + ", level " + strconv.Itoa(e.Level) + "\n")
		} else {
			b.WriteString("- #" + e.ID + ": 🥚 incubating\n")
		}
	}
	if !found {
		b.WriteString("_No eggs found for this address._\n")
	}
	return b.String()
}

// Render shows the full egg list at "", a single egg's detail when path is
// a numeric ID, or one owner's eggs when path is a bech32 address.
func Render(path string) string {
	path = strings.TrimPrefix(strings.TrimSpace(path), "/")
	if path == "" {
		return renderHome()
	}
	if _, err := strconv.Atoi(path); err == nil {
		return renderEgg(path, runtime.ChainHeight())
	}
	return renderOwner(path)
}

// Package erc1155 is an idiomatic gno.land port of the Solidity ERC-1155
// multi-token standard. A single realm tracks many distinct token ids, each
// with its own fungible balances. Balances are keyed by (owner, id) in an
// avl.Tree so Render can iterate deterministically.
package erc1155

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// balances maps "<owner>:<id>" -> uint64 amount.
var balances avl.Tree

// supply maps "<id>" -> uint64 total minted for that id.
var supply avl.Tree

func balKey(owner address, id int) string {
	return owner.String() + ":" + strconv.Itoa(id)
}

func supKey(id int) string {
	return strconv.Itoa(id)
}

func getBalance(owner address, id int) uint64 {
	k := balKey(owner, id)
	if !balances.Has(k) {
		return 0
	}
	return balances.Get(k).(uint64)
}

func setBalance(owner address, id int, amount uint64) {
	k := balKey(owner, id)
	if amount == 0 {
		balances.Remove(k)
		return
	}
	balances.Set(k, amount)
}

func getSupply(id int) uint64 {
	k := supKey(id)
	if !supply.Has(k) {
		return 0
	}
	return supply.Get(k).(uint64)
}

// Mint creates `amount` units of token `id` and credits them to `to`.
func Mint(cur realm, to address, id int, amount uint64) {
	if !to.IsValid() {
		panic("erc1155: mint to invalid address")
	}
	if amount == 0 {
		panic("erc1155: mint amount must be > 0")
	}
	setBalance(to, id, getBalance(to, id)+amount)
	supply.Set(supKey(id), getSupply(id)+amount)

	operator := unsafe.PreviousRealm().Address()
	chain.Emit("Mint",
		"operator", operator.String(),
		"to", to.String(),
		"id", strconv.Itoa(id),
		"amount", strconv.FormatUint(amount, 10),
	)
}

// TransferSingle moves `amount` of token `id` from the caller to `to`.
func TransferSingle(cur realm, to address, id int, amount uint64) {
	if !to.IsValid() {
		panic("erc1155: transfer to invalid address")
	}
	if amount == 0 {
		panic("erc1155: transfer amount must be > 0")
	}
	from := unsafe.PreviousRealm().Address()
	fromBal := getBalance(from, id)
	if fromBal < amount {
		panic("erc1155: insufficient balance")
	}
	setBalance(from, id, fromBal-amount)
	setBalance(to, id, getBalance(to, id)+amount)

	chain.Emit("TransferSingle",
		"from", from.String(),
		"to", to.String(),
		"id", strconv.Itoa(id),
		"amount", strconv.FormatUint(amount, 10),
	)
}

// BalanceOf returns the amount of token `id` held by `owner`.
func BalanceOf(owner address, id int) uint64 {
	return getBalance(owner, id)
}

// TotalSupply returns the total amount minted of token `id`.
func TotalSupply(id int) uint64 {
	return getSupply(id)
}

// Render prints a balances table and a per-id supply table.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# ERC-1155 Multi-Token\n\n")
	b.WriteString("A single realm holding many fungible token ids. ")
	b.WriteString("Balances are keyed by `(owner, id)`.\n\n")

	b.WriteString("## Balances\n\n")
	if balances.Size() == 0 {
		b.WriteString("_No balances yet. Call `Mint` to create tokens._\n\n")
	} else {
		b.WriteString("| Owner | ID | Amount |\n")
		b.WriteString("|---|---|---|\n")
		balances.Iterate("", "", func(key string, value interface{}) bool {
			owner, id := splitBalKey(key)
			b.WriteString("| `" + owner + "` | " + id + " | " +
				strconv.FormatUint(value.(uint64), 10) + " |\n")
			return false
		})
		b.WriteString("\n")
	}

	b.WriteString("## Supply per ID\n\n")
	if supply.Size() == 0 {
		b.WriteString("_No tokens minted._\n")
	} else {
		b.WriteString("| ID | Total Supply |\n")
		b.WriteString("|---|---|\n")
		supply.Iterate("", "", func(key string, value interface{}) bool {
			b.WriteString("| " + key + " | " +
				strconv.FormatUint(value.(uint64), 10) + " |\n")
			return false
		})
	}

	return b.String()
}

// splitBalKey splits a "<owner>:<id>" balance key. The owner (a bech32
// address) contains no ':', so the id is the substring after the last ':'.
func splitBalKey(key string) (owner, id string) {
	i := strings.LastIndex(key, ":")
	if i < 0 {
		return key, ""
	}
	return key[:i], key[i+1:]
}

package escrow

import (
	"chain"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// State constants for a deal's lifecycle.
const (
	StateOpen     = "Open"
	StateSettled  = "Settled"
	StateCanceled = "Canceled"
)

// Deal is a 2-party escrow record. Accounting only: no funds move,
// this tracks agreement and mutual confirmation between two parties.
type Deal struct {
	ID           int
	Creator      address
	Counterparty address
	Terms        string
	State        string
	CreatorOK    bool
	CounterOK    bool
}

var (
	deals  = avl.NewTree() // id (string) -> *Deal
	nextID int
)

var (
	errNotFound   = errors.New("escrow: deal not found")
	errNotParty   = errors.New("escrow: caller is not a party to this deal")
	errNotOpen    = errors.New("escrow: deal is not open")
	errNotCreator = errors.New("escrow: only the creator can cancel")
	errBadAddr    = errors.New("escrow: invalid counterparty address")
	errSelfDeal   = errors.New("escrow: counterparty must differ from creator")
)

// Create opens a new escrow deal between the caller (creator) and the
// given counterparty, governed by a free-form terms string. Returns the
// new deal id. Panics on invalid input (cross-realm abort).
func Create(cur realm, counterparty address, terms string) int {
	if !counterparty.IsValid() {
		panic(errBadAddr)
	}
	creator := unsafe.PreviousRealm().Address()
	if counterparty == creator {
		panic(errSelfDeal)
	}

	id := nextID
	nextID++

	d := &Deal{
		ID:           id,
		Creator:      creator,
		Counterparty: counterparty,
		Terms:        terms,
		State:        StateOpen,
	}
	deals.Set(strconv.Itoa(id), d)

	chain.Emit("Created", "id", strconv.Itoa(id),
		"creator", creator.String(), "counterparty", counterparty.String())
	return id
}

// Confirm records confirmation by whichever party is calling. Once both
// parties have confirmed, the deal transitions to Settled.
func Confirm(cur realm, id int) {
	d := mustGet(id)
	if d.State != StateOpen {
		panic(errNotOpen)
	}
	caller := unsafe.PreviousRealm().Address()

	switch caller {
	case d.Creator:
		d.CreatorOK = true
	case d.Counterparty:
		d.CounterOK = true
	default:
		panic(errNotParty)
	}

	chain.Emit("Confirmed", "id", strconv.Itoa(id), "party", caller.String())

	if d.CreatorOK && d.CounterOK {
		d.State = StateSettled
		chain.Emit("Settled", "id", strconv.Itoa(id))
	}
}

// Cancel voids an open deal. Only the creator may cancel, and only
// before the deal has settled.
func Cancel(cur realm, id int) {
	d := mustGet(id)
	if d.State != StateOpen {
		panic(errNotOpen)
	}
	caller := unsafe.PreviousRealm().Address()
	if caller != d.Creator {
		panic(errNotCreator)
	}
	d.State = StateCanceled
	chain.Emit("Canceled", "id", strconv.Itoa(id))
}

func mustGet(id int) *Deal {
	v := deals.Get(strconv.Itoa(id))
	if v == nil {
		panic(errNotFound)
	}
	return v.(*Deal)
}

// Render lists all escrow deals with their parties, terms, and state.
// When path is a numeric id, renders just that deal.
func Render(path string) string {
	path = strings.TrimSpace(strings.Trim(path, "/"))
	if path != "" {
		if id, err := strconv.Atoi(path); err == nil {
			v := deals.Get(strconv.Itoa(id))
			if v == nil {
				return "# Escrow\n\nDeal `" + path + "` not found.\n"
			}
			return renderOne(v.(*Deal))
		}
	}

	var b strings.Builder
	b.WriteString("# Escrow\n\n")
	b.WriteString("2-party escrow deals (accounting only — no funds move).\n\n")

	if deals.Size() == 0 {
		b.WriteString("_No deals yet._\n")
		return b.String()
	}

	b.WriteString("| ID | Creator | Counterparty | State | Confirmations | Terms |\n")
	b.WriteString("|----|---------|--------------|-------|---------------|-------|\n")
	deals.Iterate("", "", func(_ string, v interface{}) bool {
		d := v.(*Deal)
		b.WriteString("| " + strconv.Itoa(d.ID) +
			" | " + short(d.Creator) +
			" | " + short(d.Counterparty) +
			" | " + d.State +
			" | " + confs(d) +
			" | " + escapePipe(d.Terms) + " |\n")
		return false
	})
	return b.String()
}

func renderOne(d *Deal) string {
	var b strings.Builder
	b.WriteString("# Escrow Deal #" + strconv.Itoa(d.ID) + "\n\n")
	b.WriteString("- **State:** " + d.State + "\n")
	b.WriteString("- **Creator:** " + d.Creator.String() + " (" + yn(d.CreatorOK) + ")\n")
	b.WriteString("- **Counterparty:** " + d.Counterparty.String() + " (" + yn(d.CounterOK) + ")\n")
	b.WriteString("- **Terms:** " + d.Terms + "\n")
	return b.String()
}

func confs(d *Deal) string {
	n := 0
	if d.CreatorOK {
		n++
	}
	if d.CounterOK {
		n++
	}
	return strconv.Itoa(n) + "/2"
}

func yn(b bool) string {
	if b {
		return "confirmed"
	}
	return "pending"
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

func escapePipe(s string) string {
	return strings.ReplaceAll(s, "|", "\\|")
}

// Package guestbook is a public, on-chain guestbook realm for gno.land.
//
// Anyone can sign the guestbook with a short message via the Sign crossing
// function. Every entry records the caller's address, the message, and the
// block height at which it was signed. Render lists all entries newest-first
// as a Markdown table.
package guestbook

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// Entry is a single signed guestbook line.
type Entry struct {
	ID      int    // 1-based sequence number
	Author  string // bech32 address of the signer
	Message string // the message left by the signer
	Height  int64  // block height at which the entry was signed
}

const maxMessageLen = 280

var (
	// entries is keyed by a zero-padded sequence so avl iteration is ordered.
	entries = avl.NewTree()
	count   int
)

// Sign appends a new entry to the guestbook attributed to the immediate caller.
//
// It is a crossing function (gno 0.9 interrealm convention): callers invoke it
// as Sign(cross(cur), "hello"). The cur.IsCurrent() guard is the authentication
// primitive — without it a stale/forged realm value could spoof the author.
func Sign(cur realm, message string) {
	if !cur.IsCurrent() {
		panic("guestbook: spoofed realm; Sign must be called via cross(cur)")
	}

	author := cur.Previous().Address().String()
	e := addEntry(author, message, runtime.ChainHeight())

	chain.Emit("Signed",
		"id", strconv.Itoa(e.ID),
		"author", e.Author,
		"height", strconv.FormatInt(e.Height, 10),
	)
}

// addEntry validates the message and appends an entry. Non-crossing internal
// helper so the append/validation logic is unit-testable without a realm frame.
// Panics (aborting the tx, reverting state) on an invalid message.
func addEntry(author, message string, height int64) *Entry {
	msg := strings.TrimSpace(message)
	if msg == "" {
		panic("guestbook: message must not be empty")
	}
	if len(msg) > maxMessageLen {
		panic("guestbook: message too long (max " + strconv.Itoa(maxMessageLen) + " bytes)")
	}

	count++
	e := &Entry{
		ID:      count,
		Author:  author,
		Message: msg,
		Height:  height,
	}
	entries.Set(seqKey(count), e)
	return e
}

// Count returns the total number of signatures. Read-only, non-crossing.
func Count() int {
	return count
}

// Render lists every entry newest-first as a Markdown table plus a total count.
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Guestbook\n\n")

	if count == 0 {
		b.WriteString("_No one has signed yet. Be the first!_\n")
		return b.String()
	}

	b.WriteString("**Total signatures:** ")
	b.WriteString(strconv.Itoa(count))
	b.WriteString("\n\n")

	b.WriteString("| # | Who | Message | Height |\n")
	b.WriteString("|---|-----|---------|--------|\n")

	// avl iterates ascending by key; ReverseIterate gives newest-first.
	entries.ReverseIterate("", "", func(_ string, v any) bool {
		e := v.(*Entry)
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(e.ID))
		b.WriteString(" | ")
		b.WriteString(shortAddr(e.Author))
		b.WriteString(" | ")
		b.WriteString(escapeCell(e.Message))
		b.WriteString(" | ")
		b.WriteString(strconv.FormatInt(e.Height, 10))
		b.WriteString(" |\n")
		return false
	})

	return b.String()
}

// seqKey renders a sequence number as a fixed-width, zero-padded string so
// avl's lexicographic key order matches numeric order.
func seqKey(n int) string {
	s := strconv.Itoa(n)
	const width = 16
	if len(s) >= width {
		return s
	}
	return strings.Repeat("0", width-len(s)) + s
}

// shortAddr abbreviates a bech32 address for compact display.
func shortAddr(addr string) string {
	if len(addr) <= 12 {
		return addr
	}
	return addr[:8] + "…" + addr[len(addr)-4:]
}

// escapeCell neutralizes characters that would break a Markdown table cell.
func escapeCell(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "|", "\\|")
	s = strings.ReplaceAll(s, "\r\n", " ")
	s = strings.ReplaceAll(s, "\n", " ")
	s = strings.ReplaceAll(s, "\r", " ")
	return s
}

// Package hangman is a classic hangman game for gno.land.
//
// The secret word rotates every ~"day" (a fixed span of blocks) and is chosen
// deterministically from a built-in word list using runtime.ChainHeight(). All
// players share a single game per day: guesses and the wrong-count are common
// state. Guess a letter to reveal every matching position, or lose a life. Six
// wrong guesses ends the game.
package hangman

import (
	"chain"
	"chain/runtime"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// blocksPerDay is the number of blocks that constitutes one "day" / one round.
// The secret word is fixed for the whole span, then rotates.
const blocksPerDay = 7200

// maxWrong is the number of wrong guesses allowed before the game is lost.
const maxWrong = 6

// words is the built-in dictionary. Kept lowercase, letters only.
var words = []string{
	"gnoland",
	"blockchain",
	"realm",
	"crossing",
	"deterministic",
	"contract",
	"validator",
	"consensus",
	"package",
	"namespace",
	"immutable",
	"transaction",
	"signature",
	"gopher",
	"hangman",
}

// round holds the shared state for a single day's game.
type round struct {
	word    string   // the secret word for this round (lowercase)
	guessed *avl.Tree // letter (string) -> struct{}; ordered set of guesses
	wrong   int      // number of wrong guesses so far
}

// rounds maps a day index (decimal string) to its round. Persisted across calls.
var rounds = avl.NewTree()

// dayIndex returns the current day index derived from block height.
func dayIndex() int64 {
	return runtime.ChainHeight() / blocksPerDay
}

// wordForDay picks a word deterministically from the list for the given day.
func wordForDay(day int64) string {
	n := int64(len(words))
	idx := day % n
	if idx < 0 {
		idx += n
	}
	return words[idx]
}

// dayKey formats a day index as a stable decimal string key.
func dayKey(day int64) string {
	neg := day < 0
	if neg {
		day = -day
	}
	if day == 0 {
		return "0"
	}
	var b []byte
	for day > 0 {
		b = append([]byte{byte('0' + day%10)}, b...)
		day /= 10
	}
	if neg {
		b = append([]byte{'-'}, b...)
	}
	return string(b)
}

// current returns (creating if needed) the round for the current day.
func current() *round {
	day := dayIndex()
	key := dayKey(day)
	if v := rounds.Get(key); v != nil {
		return v.(*round)
	}
	r := &round{
		word:    wordForDay(day),
		guessed: avl.NewTree(),
		wrong:   0,
	}
	rounds.Set(key, r)
	return r
}

// normalizeLetter lowercases and validates a single a-z letter, returning it
// and true on success.
func normalizeLetter(letter string) (string, bool) {
	if len(letter) != 1 {
		return "", false
	}
	c := letter[0]
	if c >= 'A' && c <= 'Z' {
		c = c - 'A' + 'a'
	}
	if c < 'a' || c > 'z' {
		return "", false
	}
	return string(c), true
}

// isWon reports whether every letter of the word has been guessed.
func (r *round) isWon() bool {
	for i := 0; i < len(r.word); i++ {
		if !r.guessed.Has(string(r.word[i])) {
			return false
		}
	}
	return true
}

// isLost reports whether the wrong-count has reached the limit.
func (r *round) isLost() bool {
	return r.wrong >= maxWrong
}

// over reports whether the round is finished either way.
func (r *round) over() bool {
	return r.isWon() || r.isLost()
}

// Guess submits a single letter for the current day's shared game. It reveals
// matching letters or costs a life. Aborts on bad input or when the game is
// already over.
func Guess(cur realm, letter string) {
	c, ok := normalizeLetter(letter)
	if !ok {
		panic("guess must be a single letter a-z")
	}

	r := current()
	if r.over() {
		panic("today's game is already over")
	}
	if r.guessed.Has(c) {
		panic("letter already guessed: " + c)
	}

	r.guessed.Set(c, struct{}{})

	hit := strings.Contains(r.word, c)
	if !hit {
		r.wrong++
	}

	caller := unsafeCaller(cur)
	chain.Emit(
		"Guess",
		"letter", c,
		"hit", boolStr(hit),
		"wrong", itoa(int64(r.wrong)),
		"by", caller,
	)

	if r.isWon() {
		chain.Emit("Win", "day", dayKey(dayIndex()), "word", r.word)
	} else if r.isLost() {
		chain.Emit("Lose", "day", dayKey(dayIndex()), "word", r.word)
	}
}

// unsafeCaller returns the caller address as a string, preferring the crossing
// convention when available.
func unsafeCaller(cur realm) string {
	if cur.IsCurrent() {
		return cur.Previous().Address().String()
	}
	return ""
}

// boolStr renders a bool compactly.
func boolStr(b bool) string {
	if b {
		return "true"
	}
	return "false"
}

// itoa renders an int64 as decimal (avl-free tiny helper reused by Render).
func itoa(n int64) string {
	return dayKey(n)
}

// masked returns the word with un-guessed letters shown as underscores.
func (r *round) masked() string {
	var sb strings.Builder
	for i := 0; i < len(r.word); i++ {
		ch := string(r.word[i])
		if r.guessed.Has(ch) {
			sb.WriteString(ch)
		} else {
			sb.WriteString("_")
		}
		if i != len(r.word)-1 {
			sb.WriteString(" ")
		}
	}
	return sb.String()
}

// guessedList returns the guessed letters in sorted order, space-joined.
func (r *round) guessedList() string {
	var out []string
	r.guessed.Iterate("", "", func(key string, _ interface{}) bool {
		out = append(out, key)
		return false
	})
	return strings.Join(out, " ")
}

// gallows renders the ASCII stage for the given wrong-count (0..6).
func gallows(wrong int) string {
	stages := []string{
		// 0
		"  +---+\n  |   |\n      |\n      |\n      |\n      |\n=========",
		// 1
		"  +---+\n  |   |\n  O   |\n      |\n      |\n      |\n=========",
		// 2
		"  +---+\n  |   |\n  O   |\n  |   |\n      |\n      |\n=========",
		// 3
		"  +---+\n  |   |\n  O   |\n /|   |\n      |\n      |\n=========",
		// 4
		"  +---+\n  |   |\n  O   |\n /|\\  |\n      |\n      |\n=========",
		// 5
		"  +---+\n  |   |\n  O   |\n /|\\  |\n /    |\n      |\n=========",
		// 6
		"  +---+\n  |   |\n  O   |\n /|\\  |\n / \\  |\n      |\n=========",
	}
	if wrong < 0 {
		wrong = 0
	}
	if wrong >= len(stages) {
		wrong = len(stages) - 1
	}
	return stages[wrong]
}

// Render shows the current day's game: gallows, masked word, guesses, status.
func Render(path string) string {
	r := current()

	var sb strings.Builder
	sb.WriteString("# 🪢 Hangman\n\n")
	sb.WriteString("A new secret word every day. Everyone shares the same game — guess a letter and see it revealed for all.\n\n")
	sb.WriteString("Day: `" + dayKey(dayIndex()) + "` · Block: `" + itoa(runtime.ChainHeight()) + "`\n\n")

	sb.WriteString("```\n")
	sb.WriteString(gallows(r.wrong))
	sb.WriteString("\n```\n\n")

	sb.WriteString("## Word\n\n")
	sb.WriteString("`" + r.masked() + "`\n\n")

	sb.WriteString("Wrong: **" + itoa(int64(r.wrong)) + " / " + itoa(int64(maxWrong)) + "**  ·  Lives left: **" + itoa(int64(maxWrong-r.wrong)) + "**\n\n")

	guesses := r.guessedList()
	if guesses == "" {
		guesses = "_(none yet)_"
	}
	sb.WriteString("Guessed letters: " + guesses + "\n\n")

	sb.WriteString("## Status\n\n")
	switch {
	case r.isWon():
		sb.WriteString("🎉 **Solved!** The word was **" + r.word + "**.\n\n")
	case r.isLost():
		sb.WriteString("💀 **Game over.** The word was **" + r.word + "**. Try again next day.\n\n")
	default:
		sb.WriteString("Game in progress. Call `Guess(\"a\")` with a letter.\n\n")
	}

	sb.WriteString("---\n\n")
	sb.WriteString("### How to play\n\n")
	sb.WriteString("- `Guess(cur, \"e\")` — guess a single letter `a`–`z`.\n")
	sb.WriteString("- A hit reveals every matching position; a miss costs one of 6 lives.\n")
	sb.WriteString("- The word rotates every ~" + itoa(int64(blocksPerDay)) + " blocks.\n")
	return sb.String()
}

// Package kingofdice is a "king of the hill" dice game. Anyone can Roll a
// pseudo-random 1-100 die; beat the reigning king's roll and you dethrone
// them, becoming king yourself. The leaderboard doesn't rank raw points — it
// ranks accumulated *reign length*, measured in blocks held as king, so
// camping on a lucky high roll pays off more than a single spike.
package kingofdice

import (
	"sort"
	"strconv"

	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// playerStats is the persisted record for one address.
type playerStats struct {
	addr              address
	rolls             int
	bestRoll          int
	reigns            int
	totalReignBlocks  int64 // blocks held as king across all past reigns
}

var (
	players avl.Tree // address string -> *playerStats

	king       address
	kingRoll   int
	reignSince int64 // chain height at which the current king took the throne

	nonce     int
	totalRolls int
)

// get returns the stored *playerStats for addr, creating one if absent.
func get(addr address) *playerStats {
	key := addr.String()
	if v := players.Get(key); v != nil {
		return v.(*playerStats)
	}
	ps := &playerStats{addr: addr}
	players.Set(key, ps)
	return ps
}

// pseudoRoll derives a deterministic 1-100 value from the caller's address,
// a per-call nonce, and the current chain height, so no two calls in the
// same block from the same address collide, yet the result can't be
// pre-computed off-chain before the triggering transaction lands.
func pseudoRoll(addr address, nonce int, height int64) int {
	s := addr.String()
	var h int64
	for i := 0; i < len(s); i++ {
		h = h*31 + int64(s[i])
	}
	h += int64(nonce)*104729 + height*7919
	if h < 0 {
		h = -h
	}
	return int(h%100) + 1
}

// Roll throws the die for the caller. Rolling higher than the current king's
// roll dethrones them (crediting their finished reign in blocks) and crowns
// the caller as the new king.
func Roll(cur realm) string {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	caller := cur.Previous().Address()

	nonce++
	totalRolls++
	height := runtime.ChainHeight()
	roll := pseudoRoll(caller, nonce, height)

	ps := get(caller)
	ps.rolls++
	if roll > ps.bestRoll {
		ps.bestRoll = roll
	}

	if !king.IsValid() || roll > kingRoll {
		if king.IsValid() {
			prev := get(king)
			prev.totalReignBlocks += height - reignSince
		}
		king = caller
		kingRoll = roll
		reignSince = height
		ps.reigns++
		return "you rolled " + strconv.Itoa(roll) + " and seized the throne!"
	}

	if king == caller {
		return "you rolled " + strconv.Itoa(roll) + " — you're still king (need to beat " +
			strconv.Itoa(kingRoll) + ")"
	}
	return "you rolled " + strconv.Itoa(roll) + " — not enough to dethrone the king's " +
		strconv.Itoa(kingRoll)
}

// effectiveReignBlocks returns a player's accumulated reign length, including
// the currently-in-progress reign if they are the sitting king. It does not
// mutate state — it's a display-time projection.
func effectiveReignBlocks(ps *playerStats, height int64) int64 {
	if king.IsValid() && ps.addr == king {
		return ps.totalReignBlocks + (height - reignSince)
	}
	return ps.totalReignBlocks
}

// byReign implements sort.Interface, ranking players by effective reign
// length descending, ties broken by best roll then address so the order is
// fully deterministic.
type byReign struct {
	stats  []*playerStats
	blocks []int64
}

func (r byReign) Len() int      { return len(r.stats) }
func (r byReign) Swap(i, j int) {
	r.stats[i], r.stats[j] = r.stats[j], r.stats[i]
	r.blocks[i], r.blocks[j] = r.blocks[j], r.blocks[i]
}
func (r byReign) Less(i, j int) bool {
	if r.blocks[i] != r.blocks[j] {
		return r.blocks[i] > r.blocks[j]
	}
	if r.stats[i].bestRoll != r.stats[j].bestRoll {
		return r.stats[i].bestRoll > r.stats[j].bestRoll
	}
	return r.stats[i].addr.String() < r.stats[j].addr.String()
}

// snapshot collects all players ranked by effective reign length descending.
func snapshot(height int64) ([]*playerStats, []int64) {
	stats := make([]*playerStats, 0, players.Size())
	players.Iterate("", "", func(_ string, v any) bool {
		stats = append(stats, v.(*playerStats))
		return false
	})
	blocks := make([]int64, len(stats))
	for i, ps := range stats {
		blocks[i] = effectiveReignBlocks(ps, height)
	}
	sort.Stable(byReign{stats: stats, blocks: blocks})
	return stats, blocks
}

// medal returns the emoji for a given zero-based rank, or "" past the podium.
func medal(rank int) string {
	switch rank {
	case 0:
		return "🥇"
	case 1:
		return "🥈"
	case 2:
		return "🥉"
	default:
		return ""
	}
}

// display returns a shortened address for table display.
func display(addr address) string {
	s := addr.String()
	if len(s) > 12 {
		return s[:8] + "…" + s[len(s)-4:]
	}
	return s
}

// Render shows the current king and a reign-length leaderboard.
func Render(path string) string {
	height := runtime.ChainHeight()

	out := "# 👑 King of the Dice\n\n"
	out += "Roll higher than the reigning king to take the throne. The leaderboard " +
		"ranks total blocks held as king, not raw roll count — outlasting beats " +
		"getting lucky once.\n\n"

	if !king.IsValid() {
		out += "_No king yet. Call `Roll()` to make the first claim._\n\n"
	} else {
		out += "**Current king:** `" + display(king) + "` with a roll of **" +
			strconv.Itoa(kingRoll) + "**, reigning for **" +
			strconv.Itoa(int(height-reignSince)) + "** blocks so far.\n\n"
	}
	out += "Total rolls: **" + strconv.Itoa(totalRolls) + "**\n\n"

	stats, blocks := snapshot(height)
	if len(stats) == 0 {
		return out
	}

	out += "| Rank | Player | Blocks reigned | Reigns | Best roll | Rolls |\n"
	out += "| ---: | :--- | ---: | ---: | ---: | ---: |\n"
	for i, ps := range stats {
		rankCell := medal(i)
		if rankCell == "" {
			rankCell = strconv.Itoa(i + 1)
		}
		out += "| " + rankCell +
			" | " + display(ps.addr) +
			" | " + strconv.Itoa(int(blocks[i])) +
			" | " + strconv.Itoa(ps.reigns) +
			" | " + strconv.Itoa(ps.bestRoll) +
			" | " + strconv.Itoa(ps.rolls) + " |\n"
	}
	return out
}

package kudos

import (
	"chain"
	"chain/runtime/unsafe"
	"sort"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// counts maps an address (as string) -> number of kudos received.
var counts avl.Tree

// feed holds recent kudos, newest first, capped at feedCap entries.
var feed []kudo

const feedCap = 50

type kudo struct {
	from   address
	to     address
	reason string
}

// Give records a kudos from the caller to `to` with a reason.
// A caller cannot give kudos to themselves.
func Give(cur realm, to address, reason string) {
	from := unsafe.PreviousRealm().Address()
	if !to.IsValid() {
		panic("invalid recipient address")
	}
	if from == to {
		panic("cannot give kudos to yourself")
	}
	reason = strings.TrimSpace(reason)
	if reason == "" {
		panic("reason must not be empty")
	}

	key := to.String()
	n := int64(0)
	if v := counts.Get(key); v != nil {
		n = v.(int64)
	}
	counts.Set(key, n+1)

	// prepend newest, cap the feed
	feed = append([]kudo{{from: from, to: to, reason: reason}}, feed...)
	if len(feed) > feedCap {
		feed = feed[:feedCap]
	}

	chain.Emit("KudosGiven", "from", from.String(), "to", to.String(), "reason", reason)
}

// entry is a leaderboard row used for deterministic sorting.
type entry struct {
	addr  string
	count int64
}

// byScore sorts by count desc, then address asc for stable ties.
type byScore []entry

func (s byScore) Len() int      { return len(s) }
func (s byScore) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s byScore) Less(i, j int) bool {
	if s[i].count != s[j].count {
		return s[i].count > s[j].count
	}
	return s[i].addr < s[j].addr
}

func leaderboard() []entry {
	out := make([]entry, 0, counts.Size())
	counts.Iterate("", "", func(key string, value any) bool {
		out = append(out, entry{addr: key, count: value.(int64)})
		return false
	})
	sort.Sort(byScore(out))
	return out
}

// Render shows a leaderboard of most-received addresses and a recent feed.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# Kudos\n\n")
	b.WriteString("Give props to addresses. `Give(to, reason)` records a kudos.\n\n")

	b.WriteString("## Leaderboard\n\n")
	lb := leaderboard()
	if len(lb) == 0 {
		b.WriteString("_No kudos yet._\n\n")
	} else {
		b.WriteString("| # | Address | Kudos |\n")
		b.WriteString("| --- | --- | --- |\n")
		for i, e := range lb {
			b.WriteString("| " + strconv.Itoa(i+1) + " | " + e.addr + " | " + strconv.FormatInt(e.count, 10) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Recent kudos\n\n")
	if len(feed) == 0 {
		b.WriteString("_Nothing here yet._\n")
	} else {
		for _, k := range feed {
			b.WriteString("- " + k.from.String() + " → " + k.to.String() + ": " + k.reason + "\n")
		}
	}

	return b.String()
}

// Conway's Game of Life on Gno — the entire board lives on-chain.
// Anyone can call Step() to tick the simulation forward, load classic
// patterns, or sculpt cells one by one.
package life

import (
	"strconv"
	"strings"
)

const (
	MaxWidth  = 50
	MaxHeight = 40
)

var (
	width      = 20
	height     = 15
	cells      []bool
	generation int
	population int
)

func init() {
	initBoard(width, height)
	LoadPreset("glider")
}

func initBoard(w, h int) {
	if w < 1 {
		w = 1
	}
	if w > MaxWidth {
		w = MaxWidth
	}
	if h < 1 {
		h = 1
	}
	if h > MaxHeight {
		h = MaxHeight
	}
	width = w
	height = h
	cells = make([]bool, width*height)
	generation = 0
	population = 0
}

func cellIdx(x, y int) int {
	return y*width + x
}

func alive(x, y int) bool {
	if x < 0 || x >= width || y < 0 || y >= height {
		return false
	}
	return cells[cellIdx(x, y)]
}

func countNeighbors(x, y int) int {
	n := 0
	for dy := -1; dy <= 1; dy++ {
		for dx := -1; dx <= 1; dx++ {
			if dx == 0 && dy == 0 {
				continue
			}
			if alive(x+dx, y+dy) {
				n++
			}
		}
	}
	return n
}

// Step advances the simulation by exactly one generation.
func Step() {
	next := make([]bool, width*height)
	newPop := 0
	for y := 0; y < height; y++ {
		for x := 0; x < width; x++ {
			n := countNeighbors(x, y)
			var live bool
			if alive(x, y) {
				live = n == 2 || n == 3
			} else {
				live = n == 3
			}
			next[cellIdx(x, y)] = live
			if live {
				newPop++
			}
		}
	}
	cells = next
	population = newPop
	generation++
}

// MultiStep advances the simulation by n generations (capped at 100).
func MultiStep(n int) {
	if n < 1 {
		n = 1
	}
	if n > 100 {
		n = 100
	}
	for i := 0; i < n; i++ {
		Step()
	}
}

// SetCell sets or clears a specific cell.
func SetCell(x, y int, live bool) {
	if x < 0 || x >= width || y < 0 || y >= height {
		return
	}
	i := cellIdx(x, y)
	was := cells[i]
	cells[i] = live
	if live && !was {
		population++
	} else if !live && was {
		population--
	}
}

// Reset clears the board and resizes it to w×h.
func Reset(w, h int) {
	initBoard(w, h)
}

// LoadPreset loads a classic Game of Life pattern onto the current board.
// Names: glider, blinker, toad, beacon, block, pulsar.
func LoadPreset(name string) {
	for i := range cells {
		cells[i] = false
	}
	generation = 0
	population = 0

	cx := width / 2
	cy := height / 2

	switch name {
	case "glider":
		//  .O.
		//  ..O
		//  OOO
		SetCell(1, 0, true)
		SetCell(2, 1, true)
		SetCell(0, 2, true)
		SetCell(1, 2, true)
		SetCell(2, 2, true)

	case "blinker":
		// OOO  (period-2 oscillator)
		SetCell(cx-1, cy, true)
		SetCell(cx, cy, true)
		SetCell(cx+1, cy, true)

	case "toad":
		// period-2 oscillator
		SetCell(cx, cy-1, true)
		SetCell(cx+1, cy-1, true)
		SetCell(cx+2, cy-1, true)
		SetCell(cx-1, cy, true)
		SetCell(cx, cy, true)
		SetCell(cx+1, cy, true)

	case "beacon":
		// period-2 oscillator
		SetCell(cx-2, cy-2, true)
		SetCell(cx-1, cy-2, true)
		SetCell(cx-2, cy-1, true)
		SetCell(cx, cy, true)
		SetCell(cx+1, cy, true)
		SetCell(cx, cy+1, true)
		SetCell(cx+1, cy+1, true)

	case "block":
		// 2×2 still life
		SetCell(cx, cy, true)
		SetCell(cx+1, cy, true)
		SetCell(cx, cy+1, true)
		SetCell(cx+1, cy+1, true)

	case "pulsar":
		// period-3 oscillator (needs at least 17×17 board)
		for _, d := range []int{-4, -3, -2, 2, 3, 4} {
			SetCell(cx+d, cy-6, true)
			SetCell(cx+d, cy-1, true)
			SetCell(cx+d, cy+1, true)
			SetCell(cx+d, cy+6, true)
			SetCell(cx-6, cy+d, true)
			SetCell(cx-1, cy+d, true)
			SetCell(cx+1, cy+d, true)
			SetCell(cx+6, cy+d, true)
		}

	default:
		LoadPreset("glider")
	}
}

// Render returns a Markdown snapshot of the current board.
func Render(path string) string {
	out := "# Conway's Game of Life\n\n"
	out += "> A classic cellular automaton, ported to Gno — board state lives on-chain.\n\n"
	out += "**Generation:** " + strconv.Itoa(generation)
	out += " | **Population:** " + strconv.Itoa(population)
	out += " | **Board:** " + strconv.Itoa(width) + "×" + strconv.Itoa(height) + "\n\n"

	border := "+" + strings.Repeat("-", width) + "+\n"
	out += "```\n"
	out += border
	for y := 0; y < height; y++ {
		row := "|"
		for x := 0; x < width; x++ {
			if alive(x, y) {
				row += "O"
			} else {
				row += "."
			}
		}
		row += "|\n"
		out += row
	}
	out += border
	out += "```\n\n"

	out += "## Transactions\n\n"
	out += "| Call | Effect |\n"
	out += "|---|---|\n"
	out += "| `Step()` | Advance one generation |\n"
	out += "| `MultiStep(n)` | Advance *n* generations (max 100) |\n"
	out += "| `SetCell(x, y, alive)` | Flip a single cell |\n"
	out += "| `Reset(w, h)` | Clear and resize (max " + strconv.Itoa(MaxWidth) + "×" + strconv.Itoa(MaxHeight) + ") |\n"
	out += "| `LoadPreset(name)` | `glider` · `blinker` · `toad` · `beacon` · `block` · `pulsar` |\n\n"

	out += "## Rules\n\n"
	out += "1. A live cell with 2 or 3 live neighbours survives.\n"
	out += "2. A dead cell with exactly 3 live neighbours becomes alive.\n"
	out += "3. All other cells die or remain dead.\n"

	return out
}

package linktree

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// link is a single labeled URL on a profile.
type link struct {
	Label string
	URL   string
}

// profile is one address's personal links page.
type profile struct {
	Bio   string
	Links []link
}

// profiles maps an address (string key) to its *profile.
// avl.Tree keeps iteration deterministic for Render.
var profiles avl.Tree

// SetBio sets (or replaces) the calling address's bio.
func SetBio(cur realm, bio string) {
	addr := unsafe.PreviousRealm().Address()
	p := getOrCreate(addr.String())
	p.Bio = bio
	chain.Emit("BioSet", "addr", addr.String())
}

// AddLink appends a labeled URL to the calling address's profile.
func AddLink(cur realm, label string, url string) {
	if label == "" {
		panic("label must not be empty")
	}
	if url == "" {
		panic("url must not be empty")
	}
	addr := unsafe.PreviousRealm().Address()
	p := getOrCreate(addr.String())
	p.Links = append(p.Links, link{Label: label, URL: url})
	chain.Emit("LinkAdded", "addr", addr.String(), "label", label)
}

// RemoveLink deletes the link at index from the calling address's profile.
func RemoveLink(cur realm, index int) {
	addr := unsafe.PreviousRealm().Address()
	key := addr.String()
	v := profiles.Get(key)
	if v == nil {
		panic("no profile for caller")
	}
	p := v.(*profile)
	if index < 0 || index >= len(p.Links) {
		panic("index out of range")
	}
	p.Links = append(p.Links[:index], p.Links[index+1:]...)
	chain.Emit("LinkRemoved", "addr", key, "index", strconv.Itoa(index))
}

// getOrCreate returns the profile for key, creating an empty one if absent.
func getOrCreate(key string) *profile {
	if v := profiles.Get(key); v != nil {
		return v.(*profile)
	}
	p := &profile{}
	profiles.Set(key, p)
	return p
}

// Render shows all profiles at root, or a single profile at "/<address>".
func Render(path string) string {
	addr := strings.Trim(path, "/")
	if addr == "" {
		return renderIndex()
	}
	return renderProfile(addr)
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# Linktree\n\n")
	if profiles.Size() == 0 {
		b.WriteString("_No profiles yet. Call `SetBio` or `AddLink` to create one._\n")
		return b.String()
	}
	b.WriteString("Profiles:\n\n")
	profiles.Iterate("", "", func(key string, _ interface{}) bool {
		b.WriteString("- [")
		b.WriteString(key)
		b.WriteString("](/r/REPLACE_ADDR/linktree:")
		b.WriteString(key)
		b.WriteString(")\n")
		return false
	})
	return b.String()
}

func renderProfile(addr string) string {
	var b strings.Builder
	b.WriteString("# ")
	b.WriteString(addr)
	b.WriteString("\n\n")

	v := profiles.Get(addr)
	if v == nil {
		b.WriteString("_No profile for this address._\n")
		return b.String()
	}
	p := v.(*profile)

	if p.Bio != "" {
		b.WriteString(p.Bio)
		b.WriteString("\n\n")
	}

	if len(p.Links) == 0 {
		b.WriteString("_No links yet._\n")
		return b.String()
	}

	b.WriteString("## Links\n\n")
	for _, l := range p.Links {
		b.WriteString("- [")
		b.WriteString(l.Label)
		b.WriteString("](")
		b.WriteString(l.URL)
		b.WriteString(")\n")
	}
	return b.String()
}

package lru

import (
	"strconv"
	"strings"

	"chain"
)

// capacity is the fixed maximum number of entries the cache holds.
const capacity = 8

// node is a doubly-linked-list node holding a key/value pair.
// The list is ordered MRU (head) -> LRU (tail).
type node struct {
	key   string
	value string
	prev  *node
	next  *node
}

// cache is a fixed-capacity LRU cache backed by a doubly-linked list and
// an index from key -> node for O(1) lookups.
type cache struct {
	index map[string]*node
	head  *node // most-recently-used
	tail  *node // least-recently-used
	size  int
	hits  int
	miss  int
}

var c = &cache{index: make(map[string]*node)}

// detach removes n from the linked list (does not touch the index).
func (ca *cache) detach(n *node) {
	if n.prev != nil {
		n.prev.next = n.next
	} else {
		ca.head = n.next
	}
	if n.next != nil {
		n.next.prev = n.prev
	} else {
		ca.tail = n.prev
	}
	n.prev = nil
	n.next = nil
}

// pushFront inserts n at the head (MRU position).
func (ca *cache) pushFront(n *node) {
	n.prev = nil
	n.next = ca.head
	if ca.head != nil {
		ca.head.prev = n
	}
	ca.head = n
	if ca.tail == nil {
		ca.tail = n
	}
}

// touch moves an existing node to the MRU position.
func (ca *cache) touch(n *node) {
	ca.detach(n)
	ca.pushFront(n)
}

// evict removes the LRU entry (tail) and returns its key.
func (ca *cache) evict() string {
	n := ca.tail
	if n == nil {
		return ""
	}
	ca.detach(n)
	delete(ca.index, n.key)
	ca.size--
	return n.key
}

// Put inserts or updates key with value and marks it most-recently-used.
// Evicts the least-recently-used entry if capacity is exceeded.
func Put(cur realm, key string, value string) {
	if n, ok := c.index[key]; ok {
		n.value = value
		c.touch(n)
		chain.Emit("Put", "key", key, "op", "update")
		return
	}
	n := &node{key: key, value: value}
	c.index[key] = n
	c.pushFront(n)
	c.size++
	evicted := ""
	if c.size > capacity {
		evicted = c.evict()
	}
	if evicted != "" {
		chain.Emit("Put", "key", key, "op", "insert", "evicted", evicted)
	} else {
		chain.Emit("Put", "key", key, "op", "insert")
	}
}

// Get returns the value for key and marks it most-recently-used.
// It records a hit or a miss. The returned bool reports whether the key
// was present.
func Get(cur realm, key string) (string, bool) {
	if n, ok := c.index[key]; ok {
		c.touch(n)
		c.hits++
		chain.Emit("Get", "key", key, "result", "hit")
		return n.value, true
	}
	c.miss++
	chain.Emit("Get", "key", key, "result", "miss")
	return "", false
}

// Reset clears the cache and stats.
func Reset(cur realm) {
	c = &cache{index: make(map[string]*node)}
	chain.Emit("Reset")
}

// peek returns the value without affecting recency or stats (read helper).
func peek(key string) (string, bool) {
	if n, ok := c.index[key]; ok {
		return n.value, true
	}
	return "", false
}

// Render displays the cache contents in MRU->LRU order with stats.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# LRU Cache\n\n")
	b.WriteString("A fixed-capacity least-recently-used cache.\n\n")

	b.WriteString("## Stats\n\n")
	b.WriteString("- Capacity: " + strconv.Itoa(capacity) + "\n")
	b.WriteString("- Size: " + strconv.Itoa(c.size) + "\n")
	b.WriteString("- Hits: " + strconv.Itoa(c.hits) + "\n")
	b.WriteString("- Misses: " + strconv.Itoa(c.miss) + "\n")
	total := c.hits + c.miss
	if total > 0 {
		// integer-percent hit rate, deterministic
		rate := (c.hits * 100) / total
		b.WriteString("- Hit rate: " + strconv.Itoa(rate) + "%\n")
	} else {
		b.WriteString("- Hit rate: n/a\n")
	}
	b.WriteString("\n")

	b.WriteString("## Entries (MRU → LRU)\n\n")
	if c.head == nil {
		b.WriteString("_empty_\n")
		return b.String()
	}
	b.WriteString("| # | Key | Value |\n")
	b.WriteString("|---|-----|-------|\n")
	i := 1
	for n := c.head; n != nil; n = n.next {
		b.WriteString("| " + strconv.Itoa(i) + " | " + n.key + " | " + n.value + " |\n")
		i++
	}
	return b.String()
}

// Package memory implements "Memory Match", a concentration game on a
// 4x4 grid of 8 emoji pairs. The board is shuffled deterministically from
// the current block height (no on-chain RNG exists), so a NewGame started at
// a given height always produces the same layout.
package memory

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"
)

const gridSize = 16 // 4x4
const numPairs = 8

// faces are the 8 distinct emoji; each appears exactly twice on the board.
var faces = [numPairs]string{"🐶", "🐱", "🦊", "🐸", "🐵", "🐼", "🦁", "🐧"}

// tile holds the face index (0..7) for a cell and whether it is matched.
type tile struct {
	face    int
	matched bool
}

// board is the full game state. It is a package-level singleton so the realm
// persists a single shared game.
var board = struct {
	tiles   [gridSize]tile
	flipped []int // indices currently face-up but not yet resolved (0, 1 or 2)
	moves   int   // number of completed two-tile attempts
	pairs   int   // matched pairs so far
	height  int64 // block height the current game was seeded from
	started bool
}{}

// shuffle produces a deterministic permutation of the 16 tile faces from a
// 64-bit seed. It fills a slice with two of each face index then applies a
// Fisher-Yates shuffle driven by a simple LCG — fully deterministic, no RNG.
func shuffle(seed int64) [gridSize]tile {
	vals := make([]int, 0, gridSize)
	for i := 0; i < numPairs; i++ {
		vals = append(vals, i, i)
	}
	// LCG (Numerical Recipes constants); force unsigned-style math via uint64.
	state := uint64(seed)*6364136223846793005 + 1442695040888963407
	for i := len(vals) - 1; i > 0; i-- {
		state = state*6364136223846793005 + 1442695040888963407
		j := int(state % uint64(i+1))
		vals[i], vals[j] = vals[j], vals[i]
	}
	var out [gridSize]tile
	for i := 0; i < gridSize; i++ {
		out[i] = tile{face: vals[i], matched: false}
	}
	return out
}

func ensureStarted() {
	if !board.started {
		reset(runtime.ChainHeight())
	}
}

func reset(height int64) {
	board.tiles = shuffle(height)
	board.flipped = nil
	board.moves = 0
	board.pairs = 0
	board.height = height
	board.started = true
}

// NewGame reshuffles the board using the current block height as the seed.
func NewGame(cur realm) {
	reset(runtime.ChainHeight())
	chain.Emit("NewGame", "height", strconv.FormatInt(board.height, 10))
}

// Flip reveals the tile at index (0..15).
//
// Rules:
//   - If two tiles are already showing from a previous unmatched attempt,
//     this Flip first clears them (they turn back to hidden), then reveals
//     the requested tile as the first of a new attempt.
//   - Revealing the second tile of an attempt completes a move: matching
//     faces stay face-up (matched); a mismatch leaves both showing until the
//     next Flip clears them.
//   - Flipping an already-matched or already-showing tile is rejected.
func Flip(cur realm, index int) {
	ensureStarted()

	if index < 0 || index >= gridSize {
		panic("index out of range")
	}
	if board.tiles[index].matched {
		panic("tile already matched")
	}

	// A completed unmatched attempt (2 face-up, non-matching) is cleared
	// before the next reveal.
	if len(board.flipped) == 2 {
		board.flipped = nil
	}

	for _, f := range board.flipped {
		if f == index {
			panic("tile already flipped")
		}
	}

	board.flipped = append(board.flipped, index)

	if len(board.flipped) != 2 {
		chain.Emit("Flip", "index", strconv.Itoa(index))
		return
	}

	// Second tile of the attempt: resolve.
	board.moves++
	a, b := board.flipped[0], board.flipped[1]
	if board.tiles[a].face == board.tiles[b].face {
		board.tiles[a].matched = true
		board.tiles[b].matched = true
		board.pairs++
		board.flipped = nil
		chain.Emit("Match", "index", strconv.Itoa(index), "pairs", strconv.Itoa(board.pairs))
	} else {
		// leave both showing; next Flip clears them
		chain.Emit("Miss", "index", strconv.Itoa(index))
	}
}

func solved() bool {
	return board.pairs == numPairs
}

// cellFace returns the emoji to display for a cell given the current state.
func cellFace(i int) string {
	if board.tiles[i].matched {
		return faces[board.tiles[i].face]
	}
	for _, f := range board.flipped {
		if f == i {
			return faces[board.tiles[i].face]
		}
	}
	return "❓"
}

// Render draws the board as Markdown: a 4x4 grid, move count and solved state.
func Render(path string) string {
	ensureStarted()

	var sb strings.Builder
	sb.WriteString("# 🧠 Memory Match\n\n")
	sb.WriteString("Match all 8 emoji pairs on the 4x4 grid.\n\n")

	sb.WriteString("| | | | |\n")
	sb.WriteString("|:-:|:-:|:-:|:-:|\n")
	for row := 0; row < 4; row++ {
		sb.WriteString("|")
		for col := 0; col < 4; col++ {
			sb.WriteString(" " + cellFace(row*4+col) + " |")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("\n")
	sb.WriteString("- Moves: **" + strconv.Itoa(board.moves) + "**\n")
	sb.WriteString("- Pairs matched: **" + strconv.Itoa(board.pairs) + " / " + strconv.Itoa(numPairs) + "**\n")
	sb.WriteString("- Seed height: **" + strconv.FormatInt(board.height, 10) + "**\n\n")

	if solved() {
		sb.WriteString("🎉 **Solved in " + strconv.Itoa(board.moves) + " moves!** Call `NewGame` to play again.\n")
	} else {
		sb.WriteString("Call `Flip(index)` with a cell index 0–15. `NewGame()` reshuffles.\n")
	}

	return sb.String()
}

// Package multisig implements an M-of-N approval multisig realm.
//
// It is a port of the classic Solidity multisig idea: a fixed set of owners
// is configured once, any owner may create a proposal, owners approve it, and
// once the number of distinct approvals reaches the threshold the proposal is
// marked "Executed". This realm tracks approvals only — it does not move funds.
package multisig

import (
	"errors"
	"strconv"
	"strings"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// State of a single proposal.
type stateKind int

const (
	statePending stateKind = iota
	stateExecuted
)

func (s stateKind) String() string {
	if s == stateExecuted {
		return "Executed"
	}
	return "Pending"
}

// proposal is a single approval request.
type proposal struct {
	id          int
	description string
	proposer    address
	approvals   *avl.Tree // owner address string -> struct{}{}, distinct approvers
	state       stateKind
}

// Package-level persistent state.
var (
	owners      *avl.Tree // owner address string -> struct{}{}
	ownerCount  int
	threshold   int
	initialized bool

	proposals   *avl.Tree // decimal id string -> *proposal
	nextID      int
)

var (
	errAlreadyInit = errors.New("multisig: already initialized")
	errNotInit     = errors.New("multisig: not initialized")
	errBadThreshold = errors.New("multisig: threshold must be between 1 and number of owners")
	errNoOwners    = errors.New("multisig: at least one owner required")
	errNotOwner    = errors.New("multisig: caller is not an owner")
	errNoProposal  = errors.New("multisig: proposal not found")
	errDupApproval = errors.New("multisig: caller already approved this proposal")
	errExecuted    = errors.New("multisig: proposal already executed")
)

func init() {
	owners = avl.NewTree()
	proposals = avl.NewTree()
}

// caller returns the address of the realm/user that called into this realm.
func caller() address {
	return unsafe.PreviousRealm().Address()
}

func isOwner(a address) bool {
	return owners.Has(a.String())
}

// Setup configures the multisig exactly once. owners is a comma-separated list
// of bech32 addresses; threshold is the number of approvals required to execute
// a proposal. It panics (cross-realm abort) on invalid input or if already set.
func Setup(cur realm, ownersCSV string, thresholdN int) {
	if initialized {
		panic(errAlreadyInit)
	}

	parts := strings.Split(ownersCSV, ",")
	count := 0
	for _, p := range parts {
		a := strings.TrimSpace(p)
		if a == "" {
			continue
		}
		addr := address(a)
		if owners.Has(addr.String()) {
			continue // dedupe
		}
		owners.Set(addr.String(), struct{}{})
		count++
	}
	if count == 0 {
		panic(errNoOwners)
	}
	if thresholdN < 1 || thresholdN > count {
		panic(errBadThreshold)
	}

	ownerCount = count
	threshold = thresholdN
	initialized = true

	chain.Emit("Setup", "owners", strconv.Itoa(count), "threshold", strconv.Itoa(thresholdN))
}

// Propose creates a new proposal authored by an owner and returns its id.
func Propose(cur realm, description string) int {
	if !initialized {
		panic(errNotInit)
	}
	c := caller()
	if !isOwner(c) {
		panic(errNotOwner)
	}

	id := nextID
	nextID++

	p := &proposal{
		id:          id,
		description: description,
		proposer:    c,
		approvals:   avl.NewTree(),
		state:       statePending,
	}
	proposals.Set(strconv.Itoa(id), p)

	chain.Emit("Propose", "id", strconv.Itoa(id), "proposer", c.String())
	return id
}

// Approve records an owner's approval for a proposal. When the count of distinct
// approvals reaches the threshold, the proposal becomes Executed.
func Approve(cur realm, id int) {
	if !initialized {
		panic(errNotInit)
	}
	c := caller()
	if !isOwner(c) {
		panic(errNotOwner)
	}

	v := proposals.Get(strconv.Itoa(id))
	if v == nil {
		panic(errNoProposal)
	}
	p := v.(*proposal)
	if p.state == stateExecuted {
		panic(errExecuted)
	}
	if p.approvals.Has(c.String()) {
		panic(errDupApproval)
	}

	p.approvals.Set(c.String(), struct{}{})
	chain.Emit("Approve", "id", strconv.Itoa(id), "owner", c.String(), "approvals", strconv.Itoa(p.approvals.Size()))

	if p.approvals.Size() >= threshold {
		p.state = stateExecuted
		chain.Emit("Executed", "id", strconv.Itoa(id))
	}
}

// Render returns a Markdown view of the multisig configuration and proposals.
func Render(path string) string {
	var b strings.Builder
	b.WriteString("# M-of-N Multisig\n\n")

	if !initialized {
		b.WriteString("_Not initialized. Call `Setup(owners, threshold)` once._\n")
		return b.String()
	}

	b.WriteString("**Threshold:** ")
	b.WriteString(strconv.Itoa(threshold))
	b.WriteString(" of ")
	b.WriteString(strconv.Itoa(ownerCount))
	b.WriteString("\n\n## Owners\n\n")
	owners.Iterate("", "", func(key string, _ interface{}) bool {
		b.WriteString("- `")
		b.WriteString(key)
		b.WriteString("`\n")
		return false
	})

	b.WriteString("\n## Proposals\n\n")
	if proposals.Size() == 0 {
		b.WriteString("_No proposals yet._\n")
		return b.String()
	}

	b.WriteString("| ID | Description | Proposer | Approvals | State |\n")
	b.WriteString("|----|-------------|----------|-----------|-------|\n")
	proposals.Iterate("", "", func(_ string, v interface{}) bool {
		p := v.(*proposal)
		b.WriteString("| ")
		b.WriteString(strconv.Itoa(p.id))
		b.WriteString(" | ")
		b.WriteString(p.description)
		b.WriteString(" | `")
		b.WriteString(p.proposer.String())
		b.WriteString("` | ")
		b.WriteString(strconv.Itoa(p.approvals.Size()))
		b.WriteString("/")
		b.WriteString(strconv.Itoa(threshold))
		b.WriteString(" | ")
		b.WriteString(p.state.String())
		b.WriteString(" |\n")
		return false
	})

	return b.String()
}

// Package polls is an on-chain poll / voting realm for gno.land.
//
// Anyone can create a poll with a question and a comma-separated list of
// options. Each caller address may cast exactly one vote per poll. Render
// draws every poll with its options, tallies as ▓░ bar charts, percentages
// and the total vote count.
package polls

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Poll is a single question with its options and per-address vote tracking.
type Poll struct {
	ID       int
	Question string
	Options  []string
	Tallies  []int
	Creator  string    // bech32 address of the poll creator
	voted    *avl.Tree // address string -> struct{}{}, one vote per address
}

var (
	polls  []*Poll // index i holds the poll with ID i
	nextID int
)

// CreatePoll registers a new poll. options is a comma-separated list; blank
// entries are dropped. Returns the new poll's id. Crossing function: an EOA
// invokes it via MsgCall; another realm via polls.CreatePoll(cross, q, opts).
func CreatePoll(cur realm, question string, options string) int {
	creator := unsafe.PreviousRealm().Address().String()

	q := strings.TrimSpace(question)
	if q == "" {
		panic("question must not be empty")
	}

	opts := parseOptions(options)
	if len(opts) < 2 {
		panic("a poll needs at least 2 options")
	}

	id := nextID
	nextID++
	p := &Poll{
		ID:       id,
		Question: q,
		Options:  opts,
		Tallies:  make([]int, len(opts)),
		Creator:  creator,
		voted:    avl.NewTree(),
	}
	polls = append(polls, p)

	chain.Emit("PollCreated",
		"id", strconv.Itoa(id),
		"creator", creator,
		"options", strconv.Itoa(len(opts)),
	)
	return id
}

// Vote casts one vote for optionIndex on poll pollID. Each caller address may
// vote at most once per poll. Crossing function.
func Vote(cur realm, pollID int, optionIndex int) {
	voter := unsafe.PreviousRealm().Address().String()

	p := getPoll(pollID)
	if optionIndex < 0 || optionIndex >= len(p.Options) {
		panic("option index out of range")
	}
	if p.voted.Has(voter) {
		panic("address already voted on this poll")
	}

	p.voted.Set(voter, struct{}{})
	p.Tallies[optionIndex]++

	chain.Emit("Voted",
		"id", strconv.Itoa(pollID),
		"voter", voter,
		"option", strconv.Itoa(optionIndex),
	)
}

// parseOptions splits a comma-separated option string, trimming whitespace and
// dropping empties. Pure logic — no realm state.
func parseOptions(options string) []string {
	var out []string
	for _, raw := range strings.Split(options, ",") {
		o := strings.TrimSpace(raw)
		if o != "" {
			out = append(out, o)
		}
	}
	return out
}

// getPoll returns the poll with the given id or panics if it does not exist.
func getPoll(id int) *Poll {
	if id < 0 || id >= len(polls) {
		panic("poll not found")
	}
	return polls[id]
}

// PollCount returns the number of polls created so far (read-only helper).
func PollCount() int {
	return len(polls)
}

const barWidth = 20

// bar renders a proportional ▓░ bar of fixed width for count out of total.
func bar(count, total int) string {
	filled := 0
	if total > 0 {
		filled = count * barWidth / total
	}
	if filled > barWidth {
		filled = barWidth
	}
	return strings.Repeat("▓", filled) + strings.Repeat("░", barWidth-filled)
}

// percent returns the integer percentage of count out of total.
func percent(count, total int) int {
	if total == 0 {
		return 0
	}
	return count * 100 / total
}

// total sums a tally slice.
func total(tallies []int) int {
	sum := 0
	for _, t := range tallies {
		sum += t
	}
	return sum
}

// renderPoll writes one poll's Markdown block into b.
func renderPoll(b *strings.Builder, p *Poll) {
	sum := total(p.Tallies)

	b.WriteString("## Poll #")
	b.WriteString(strconv.Itoa(p.ID))
	b.WriteString(": ")
	b.WriteString(p.Question)
	b.WriteString("\n\n")

	for i, opt := range p.Options {
		c := p.Tallies[i]
		b.WriteString("- **")
		b.WriteString(opt)
		b.WriteString("** `")
		b.WriteString(bar(c, sum))
		b.WriteString("` ")
		b.WriteString(strconv.Itoa(percent(c, sum)))
		b.WriteString("% (")
		b.WriteString(strconv.Itoa(c))
		if c == 1 {
			b.WriteString(" vote)")
		} else {
			b.WriteString(" votes)")
		}
		b.WriteString("\n")
	}

	b.WriteString("\n_Total votes: ")
	b.WriteString(strconv.Itoa(sum))
	b.WriteString("_\n\n")
}

// Render produces the Markdown page for gnoweb. It is NOT a crossing function.
//
//   - ""        -> index of all polls
//   - "<id>"    -> a single poll by id
func Render(path string) string {
	var b strings.Builder

	path = strings.TrimSpace(path)
	if path != "" {
		id, err := strconv.Atoi(path)
		if err != nil || id < 0 || id >= len(polls) {
			return "# Polls\n\nPoll not found.\n"
		}
		b.WriteString("# Polls\n\n")
		renderPoll(&b, polls[id])
		b.WriteString("[← all polls](/r/REPLACE_ADDR/polls)\n")
		return b.String()
	}

	b.WriteString("# Polls & Voting\n\n")
	if len(polls) == 0 {
		b.WriteString("_No polls yet. Create one with `CreatePoll(question, \"a,b,c\")`._\n")
		return b.String()
	}

	b.WriteString("Total polls: ")
	b.WriteString(strconv.Itoa(len(polls)))
	b.WriteString("\n\n")
	for _, p := range polls {
		renderPoll(&b, p)
	}
	return b.String()
}

// Package reactions is an emoji reaction board.
//
// Each topic collects emoji reactions. A caller may register at most one
// reaction per topic; the emoji they picked increments a per-topic per-emoji
// tally. Render lists every topic with its emoji tallies and total count.
package reactions

import (
	"sort"
	"strconv"
	"strings"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// topic holds the tallies and the set of callers who already reacted.
type topic struct {
	name    string
	tallies *avl.Tree // emoji (string) -> count (int)
	voters  *avl.Tree // caller address (string) -> struct{}
	total   int
}

// topics maps topic name -> *topic, kept in an avl.Tree for deterministic order.
var topics = avl.NewTree()

func getOrPanic(name string) *topic {
	v := topics.Get(name)
	if v == nil {
		panic("topic does not exist: " + name)
	}
	return v.(*topic)
}

func newTopic(name string) *topic {
	t := &topic{
		name:    name,
		tallies: avl.NewTree(),
		voters:  avl.NewTree(),
	}
	topics.Set(name, t)
	return t
}

// CreateTopic registers a new empty topic. It is optional: React auto-creates
// a topic if it does not exist yet. Panics if the topic already exists or the
// name is empty.
func CreateTopic(cur realm, name string) {
	name = strings.TrimSpace(name)
	if name == "" {
		panic("topic name must not be empty")
	}
	if topics.Has(name) {
		panic("topic already exists: " + name)
	}
	newTopic(name)
	chain.Emit("TopicCreated", "topic", name)
}

// React adds the caller's reaction (an emoji) to a topic. Each caller may react
// at most once per topic. The topic is created on demand if missing. Panics on
// empty input or when the caller has already reacted to this topic.
func React(cur realm, name, emoji string) {
	name = strings.TrimSpace(name)
	emoji = strings.TrimSpace(emoji)
	if name == "" {
		panic("topic name must not be empty")
	}
	if emoji == "" {
		panic("emoji must not be empty")
	}

	caller := unsafe.PreviousRealm().Address().String()

	var t *topic
	if v := topics.Get(name); v != nil {
		t = v.(*topic)
	} else {
		t = newTopic(name)
	}

	if t.voters.Has(caller) {
		panic("caller already reacted to this topic: " + name)
	}
	t.voters.Set(caller, struct{}{})

	count := 0
	if v := t.tallies.Get(emoji); v != nil {
		count = v.(int)
	}
	t.tallies.Set(emoji, count+1)
	t.total++

	chain.Emit("Reacted", "topic", name, "emoji", emoji)
}

// TopicCount returns the number of topics on the board.
func TopicCount() int {
	return topics.Size()
}

// emojiTally is used to sort a topic's tallies deterministically.
type emojiTally struct {
	emoji string
	count int
}

// byCountDesc sorts tallies by count descending, then emoji ascending.
type byCountDesc []emojiTally

func (s byCountDesc) Len() int      { return len(s) }
func (s byCountDesc) Swap(i, j int) { s[i], s[j] = s[j], s[i] }
func (s byCountDesc) Less(i, j int) bool {
	if s[i].count != s[j].count {
		return s[i].count > s[j].count
	}
	return s[i].emoji < s[j].emoji
}

func (t *topic) sortedTallies() []emojiTally {
	out := make([]emojiTally, 0, t.tallies.Size())
	t.tallies.Iterate("", "", func(key string, value interface{}) bool {
		out = append(out, emojiTally{emoji: key, count: value.(int)})
		return false
	})
	sort.Stable(byCountDesc(out))
	return out
}

// tallyRow renders a topic's tallies as e.g. "👍 3  ❤️ 5  🎉 1".
func (t *topic) tallyRow() string {
	if t.tallies.Size() == 0 {
		return "_no reactions yet_"
	}
	rows := t.sortedTallies()
	parts := make([]string, 0, len(rows))
	for _, r := range rows {
		parts = append(parts, r.emoji+" "+strconv.Itoa(r.count))
	}
	return strings.Join(parts, "  ")
}

// Render returns a Markdown view of the board. If path is a non-empty topic
// name, only that topic is shown; otherwise all topics are listed.
func Render(path string) string {
	path = strings.TrimSpace(strings.Trim(path, "/"))

	if path != "" {
		v := topics.Get(path)
		if v == nil {
			return "# Reaction Board\n\nTopic not found: `" + path + "`\n"
		}
		t := v.(*topic)
		var sb strings.Builder
		sb.WriteString("# Reaction Board — " + t.name + "\n\n")
		sb.WriteString(t.tallyRow() + "\n\n")
		sb.WriteString("**Total reactions:** " + strconv.Itoa(t.total) + "\n")
		return sb.String()
	}

	var sb strings.Builder
	sb.WriteString("# Reaction Board\n\n")
	if topics.Size() == 0 {
		sb.WriteString("_No topics yet. Call `React(cur, topic, emoji)` to start._\n")
		return sb.String()
	}

	grand := 0
	topics.Iterate("", "", func(key string, value interface{}) bool {
		t := value.(*topic)
		grand += t.total
		sb.WriteString("## " + t.name + "\n\n")
		sb.WriteString(t.tallyRow() + "\n\n")
		sb.WriteString("Total: " + strconv.Itoa(t.total) + "\n\n")
		return false
	})

	sb.WriteString("---\n\n")
	sb.WriteString("**Topics:** " + strconv.Itoa(topics.Size()) +
		" · **Reactions:** " + strconv.Itoa(grand) + "\n")
	return sb.String()
}

// Package rpsduel is an asynchronous, two-player rock-paper-scissors duel
// with a commit-reveal handshake. The challenger locks in a move as a
// sha256 commitment up front so the opponent can't peek at it; the
// opponent then replies in the clear (seeing only a hash gives them no
// edge); the challenger reveals last to settle the round. A challenger who
// tries to dodge a losing reveal can be forfeited by the opponent once the
// reveal window expires.
package rpsduel

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// Move is one of rock, paper, or scissors, ordered so that
// (winner - loser + 3) % 3 == 1 for every winning pair.
type Move int

const (
	Rock Move = iota
	Paper
	Scissors
)

func moveName(m Move) string {
	switch m {
	case Rock:
		return "rock"
	case Paper:
		return "paper"
	case Scissors:
		return "scissors"
	default:
		return "?"
	}
}

func parseMove(s string) (Move, bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "rock", "r":
		return Rock, true
	case "paper", "p":
		return Paper, true
	case "scissors", "s":
		return Scissors, true
	default:
		return 0, false
	}
}

// judge returns 0 for a tie, 1 if p beats h, 2 if h beats p.
func judge(p, h Move) int {
	return (int(p) - int(h) + 3) % 3
}

// revealWindow is how many blocks the challenger gets to reveal after the
// opponent accepts before the opponent can claim a forfeit win.
const revealWindow int64 = 50

type duelStatus int

const (
	statusPending duelStatus = iota
	statusAwaitingReveal
	statusResolved
	statusForfeited
	statusCancelled
)

func (s duelStatus) String() string {
	switch s {
	case statusPending:
		return "pending"
	case statusAwaitingReveal:
		return "awaiting reveal"
	case statusResolved:
		return "resolved"
	case statusForfeited:
		return "forfeited"
	case statusCancelled:
		return "cancelled"
	default:
		return "?"
	}
}

// duel is one asynchronous round between Challenger and Opponent. The
// challenger's move is hidden behind Commit until Reveal; the opponent's
// move is stored in the clear once they Accept.
type duel struct {
	ID             string
	Challenger     address
	Opponent       address
	Commit         string // hex sha256 of "<move>:<salt>"
	OpponentMove   Move
	Status         duelStatus
	Result         string // "challenger" | "opponent" | "draw" once settled
	Winner         address
	OpenedAt       int64
	AcceptedAt     int64
	RevealDeadline int64
}

// playerState is the persisted record for one address.
type playerState struct {
	Wins     int
	Losses   int
	Draws    int
	Forfeits int // times this player, as challenger, failed to reveal in time
	Duels    int
}

var (
	duels   avl.Tree // duel ID -> *duel
	players avl.Tree // address string -> *playerState

	nextID        int
	totalResolved int

	champion     address
	championWins int
)

// ComputeCommit hashes a move and salt exactly the way Reveal checks it, so
// a caller can compute their commitment (e.g. via a read-only query) before
// calling Open, then remember the salt to pass to Reveal later.
func ComputeCommit(moveStr, salt string) string {
	m, ok := parseMove(moveStr)
	if !ok {
		panic("invalid move: use rock, paper, or scissors (r/p/s)")
	}
	sum := sha256.Sum256([]byte(moveName(m) + ":" + salt))
	return hex.EncodeToString(sum[:])
}

func getOrCreate(addr address) *playerState {
	key := addr.String()
	if v := players.Get(key); v != nil {
		return v.(*playerState)
	}
	ps := &playerState{}
	players.Set(key, ps)
	return ps
}

func bumpChampion(addr address, wins int) {
	if wins > championWins {
		championWins = wins
		champion = addr
	}
}

// settle scores a revealed round and updates both players' records.
func settle(d *duel, challengerMove Move, result int) {
	cs := getOrCreate(d.Challenger)
	os := getOrCreate(d.Opponent)
	cs.Duels++
	os.Duels++

	switch result {
	case 1:
		cs.Wins++
		os.Losses++
		d.Winner = d.Challenger
		d.Result = "challenger"
		bumpChampion(d.Challenger, cs.Wins)
	case 2:
		os.Wins++
		cs.Losses++
		d.Winner = d.Opponent
		d.Result = "opponent"
		bumpChampion(d.Opponent, os.Wins)
	default:
		cs.Draws++
		os.Draws++
		d.Result = "draw"
	}
	d.Status = statusResolved
	totalResolved++
}

// Open challenges opponentAddr to a duel, locking in the challenger's move
// as a commitment (see ComputeCommit) so the opponent can't see it before
// replying.
func Open(cur realm, opponentAddr string, commitHex string) string {
	challenger := cur.Previous().Address()

	opponent := address(strings.TrimSpace(opponentAddr))
	if !opponent.IsValid() {
		panic("invalid opponent address")
	}
	if opponent == challenger {
		panic("cannot duel yourself")
	}

	commit := strings.ToLower(strings.TrimSpace(commitHex))
	if len(commit) != sha256.Size*2 {
		panic("commit must be a 64-character hex sha256 digest; build it with ComputeCommit")
	}
	if _, err := hex.DecodeString(commit); err != nil {
		panic("commit must be valid hex")
	}

	nextID++
	id := strconv.Itoa(nextID)
	d := &duel{
		ID:         id,
		Challenger: challenger,
		Opponent:   opponent,
		Commit:     commit,
		Status:     statusPending,
		OpenedAt:   runtime.ChainHeight(),
	}
	duels.Set(id, d)

	chain.Emit("DuelOpened",
		"id", id,
		"challenger", challenger.String(),
		"opponent", opponent.String(),
	)

	return "duel #" + id + " opened against " + opponent.String() + " -- waiting for them to Accept"
}

// Accept replies to a pending duel with a plain move. Only the challenged
// opponent may call it; going second behind the challenger's hidden
// commitment is what keeps this fair.
func Accept(cur realm, id string, moveStr string) string {
	caller := cur.Previous().Address()

	v := duels.Get(id)
	if v == nil {
		panic("no such duel")
	}
	d := v.(*duel)

	if d.Status != statusPending {
		panic("duel is " + d.Status.String() + ", not pending")
	}
	if caller != d.Opponent {
		panic("only the challenged opponent can accept this duel")
	}

	m, ok := parseMove(moveStr)
	if !ok {
		panic("invalid move: use rock, paper, or scissors (r/p/s)")
	}

	d.OpponentMove = m
	d.Status = statusAwaitingReveal
	d.AcceptedAt = runtime.ChainHeight()
	d.RevealDeadline = d.AcceptedAt + revealWindow

	chain.Emit("DuelAccepted", "id", id, "opponentMove", moveName(m))

	return "you played " + moveName(m) + " in duel #" + id +
		" -- waiting for " + d.Challenger.String() + " to reveal by block " +
		strconv.Itoa(int(d.RevealDeadline))
}

// Reveal settles an accepted duel. Only the original challenger may call
// it, and only with the exact move+salt that produced their commitment.
func Reveal(cur realm, id string, moveStr string, salt string) string {
	caller := cur.Previous().Address()

	v := duels.Get(id)
	if v == nil {
		panic("no such duel")
	}
	d := v.(*duel)

	if d.Status != statusAwaitingReveal {
		panic("duel is " + d.Status.String() + ", not awaiting reveal")
	}
	if caller != d.Challenger {
		panic("only the challenger can reveal")
	}

	m, ok := parseMove(moveStr)
	if !ok {
		panic("invalid move: use rock, paper, or scissors (r/p/s)")
	}
	sum := sha256.Sum256([]byte(moveName(m) + ":" + salt))
	if hex.EncodeToString(sum[:]) != d.Commit {
		panic("revealed move+salt doesn't match your original commitment")
	}

	result := judge(m, d.OpponentMove)
	settle(d, m, result)

	chain.Emit("DuelResolved",
		"id", id,
		"result", d.Result,
		"challengerMove", moveName(m),
		"opponentMove", moveName(d.OpponentMove),
	)

	return "you revealed " + moveName(m) + " vs " + moveName(d.OpponentMove) + " -- " + outcomeMsg(d)
}

func outcomeMsg(d *duel) string {
	switch d.Result {
	case "challenger":
		return "you win duel #" + d.ID + "!"
	case "opponent":
		return "you lose duel #" + d.ID + " -- " + d.Opponent.String() + " wins."
	default:
		return "draw."
	}
}

// ClaimForfeit lets the opponent collect a default win when the challenger
// dodges revealing (e.g. because they saw the opponent's move and knew
// they'd lose) past the reveal window.
func ClaimForfeit(cur realm, id string) string {
	caller := cur.Previous().Address()

	v := duels.Get(id)
	if v == nil {
		panic("no such duel")
	}
	d := v.(*duel)

	if d.Status != statusAwaitingReveal {
		panic("duel is " + d.Status.String() + ", not awaiting reveal")
	}
	if caller != d.Opponent {
		panic("only the waiting opponent can claim a forfeit")
	}
	if runtime.ChainHeight() <= d.RevealDeadline {
		panic("reveal window hasn't expired yet")
	}

	d.Status = statusForfeited
	d.Winner = d.Opponent
	d.Result = "opponent"

	cs := getOrCreate(d.Challenger)
	cs.Duels++
	cs.Losses++
	cs.Forfeits++
	os := getOrCreate(d.Opponent)
	os.Duels++
	os.Wins++
	totalResolved++
	bumpChampion(d.Opponent, os.Wins)

	chain.Emit("DuelForfeited", "id", id, "winner", d.Opponent.String())

	return "duel #" + id + " forfeited -- " + d.Challenger.String() + " never revealed"
}

// Cancel withdraws a still-pending duel. Only the challenger may cancel,
// and only before the opponent accepts.
func Cancel(cur realm, id string) string {
	caller := cur.Previous().Address()

	v := duels.Get(id)
	if v == nil {
		panic("no such duel")
	}
	d := v.(*duel)

	if d.Status != statusPending {
		panic("duel is " + d.Status.String() + ", not pending")
	}
	if caller != d.Challenger {
		panic("only the challenger can cancel this duel")
	}

	d.Status = statusCancelled
	return "duel #" + id + " cancelled"
}

// escapeInline neutralizes markdown-active characters in untrusted text
// before it's embedded inline in Render output.
func escapeInline(s string) string {
	r := strings.NewReplacer(
		"\\", "\\\\",
		"`", "\\`",
		"*", "\\*",
		"_", "\\_",
		"[", "\\[",
		"]", "\\]",
		"|", "\\|",
	)
	return r.Replace(s)
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Rock-Paper-Scissors Duel\n\n")
	b.WriteString("Challenge another address to rock-paper-scissors, async and " +
		"fair: you commit your move as a hash, they reply in the open, then you " +
		"reveal to settle it. Stall on revealing a losing round and your opponent " +
		"can claim a forfeit win once the window expires.\n\n")

	b.WriteString("- Total duels resolved: " + strconv.Itoa(totalResolved) + "\n")
	if champion.IsValid() {
		b.WriteString("- Reigning champion: `" + champion.String() + "` (" +
			strconv.Itoa(championWins) + " wins)\n")
	} else {
		b.WriteString("- No champion yet -- be the first to win a duel.\n")
	}

	b.WriteString("\n## How to play\n\n")
	b.WriteString("1. Pick a move and a random salt, e.g. `rock` + `xyz123`.\n")
	b.WriteString("2. Compute your commitment: `ComputeCommit(\"rock\", \"xyz123\")` (read-only call).\n")
	b.WriteString("3. `Open(opponentAddr, commit)` -- opens the duel, returns its ID.\n")
	b.WriteString("4. The opponent calls `Accept(id, \"paper\"|\"scissors\"|\"rock\")`.\n")
	b.WriteString("5. You call `Reveal(id, \"rock\", \"xyz123\")` -- must match your commitment exactly.\n")
	b.WriteString("6. If you never reveal, the opponent can call `ClaimForfeit(id)` after " +
		strconv.Itoa(int(revealWindow)) + " blocks.\n\n")
	b.WriteString("View a duel at this realm's path plus its ID (e.g. `.../rpsduel:3`), " +
		"or a player's record plus their address (e.g. `.../rpsduel:g1youraddress...`).\n\n")

	b.WriteString("## Open duels\n\n")
	open := 0
	duels.Iterate("", "", func(key string, value interface{}) bool {
		d := value.(*duel)
		if d.Status == statusPending {
			open++
			b.WriteString("- #" + d.ID + ": `" + d.Challenger.String() +
				"` waiting on `" + d.Opponent.String() + "` to Accept\n")
		} else if d.Status == statusAwaitingReveal {
			open++
			b.WriteString("- #" + d.ID + ": `" + d.Challenger.String() +
				"` must Reveal by block " + strconv.Itoa(int(d.RevealDeadline)) + "\n")
		}
		return false
	})
	if open == 0 {
		b.WriteString("_none right now_\n")
	}

	return b.String()
}

func renderDuel(id string) string {
	v := duels.Get(id)
	if v == nil {
		return "# Duel #" + escapeInline(id) + "\n\nNo such duel.\n"
	}
	d := v.(*duel)

	var b strings.Builder
	b.WriteString("# Duel #" + d.ID + "\n\n")
	b.WriteString("- Challenger: `" + d.Challenger.String() + "`\n")
	b.WriteString("- Opponent: `" + d.Opponent.String() + "`\n")
	b.WriteString("- Status: " + d.Status.String() + "\n")

	if d.Status == statusAwaitingReveal {
		b.WriteString("- Opponent played: **" + moveName(d.OpponentMove) + "**\n")
		b.WriteString("- Reveal deadline: block " + strconv.Itoa(int(d.RevealDeadline)) + "\n")
	}
	if d.Status == statusResolved || d.Status == statusForfeited {
		b.WriteString("- Result: " + d.Result + "\n")
		b.WriteString("- Winner: `" + d.Winner.String() + "`\n")
	}
	return b.String()
}

func renderPlayer(rawAddr string) string {
	addr := strings.TrimSpace(rawAddr)
	safe := escapeInline(addr)

	v := players.Get(addr)
	if v == nil {
		return "# Player " + safe + "\n\nNo recorded duels yet.\n"
	}
	ps := v.(*playerState)

	var b strings.Builder
	b.WriteString("# Player " + safe + "\n\n")
	b.WriteString("- Wins: " + strconv.Itoa(ps.Wins) + "\n")
	b.WriteString("- Losses: " + strconv.Itoa(ps.Losses) + "\n")
	b.WriteString("- Draws: " + strconv.Itoa(ps.Draws) + "\n")
	b.WriteString("- Duels played: " + strconv.Itoa(ps.Duels) + "\n")
	if ps.Forfeits > 0 {
		b.WriteString("- Forfeited (didn't reveal in time): " + strconv.Itoa(ps.Forfeits) + "\n")
	}
	return b.String()
}

// Render shows the duel lobby at "", a specific duel when path is a
// numeric ID, or one player's record when path is their bech32 address.
func Render(path string) string {
	path = strings.TrimPrefix(strings.TrimSpace(path), "/")
	if path == "" {
		return renderHome()
	}
	if _, err := strconv.Atoi(path); err == nil {
		return renderDuel(path)
	}
	return renderPlayer(path)
}

// Package rpsmatch is a best-of-three rock-paper-scissors arena against the
// house. Unlike a single stateless throw, a match persists across calls:
// the first player to win two rounds takes the match, and every player's
// match record accumulates on-chain.
package rpsmatch

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// Move is one of rock, paper, or scissors, ordered so that
// (winner - loser + 3) % 3 == 1 for every winning pair.
type Move int

const (
	Rock Move = iota
	Paper
	Scissors
)

// winsNeeded is the number of round wins required to take a match.
const winsNeeded = 2

// match tracks an in-progress best-of-three series for one player.
type match struct {
	PlayerWins int
	HouseWins  int
	Rounds     int
}

// playerState is the persisted record for one address.
type playerState struct {
	Active        *match
	MatchWins     int
	MatchLosses   int
	MatchesPlayed int
	RoundsPlayed  int
}

var (
	players avl.Tree // address string -> *playerState

	nonce       int
	totalRounds int

	champion     address
	championWins int
)

func moveName(m Move) string {
	switch m {
	case Rock:
		return "rock"
	case Paper:
		return "paper"
	case Scissors:
		return "scissors"
	default:
		return "?"
	}
}

func parseMove(s string) (Move, bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "rock", "r":
		return Rock, true
	case "paper", "p":
		return Paper, true
	case "scissors", "s":
		return Scissors, true
	default:
		return 0, false
	}
}

// judge returns 0 for a tie, 1 if p beats h, 2 if h beats p.
func judge(p, h Move) int {
	return (int(p) - int(h) + 3) % 3
}

// pickHouseMove derives a deterministic pseudo-random move from the current
// chain height, a monotonic per-realm nonce, and the caller's address, so
// repeated throws in the same block still diverge.
func pickHouseMove(caller address, n int) Move {
	seed := runtime.ChainHeight() + int64(n)
	s := caller.String()
	for i := 0; i < len(s); i++ {
		seed += int64(s[i])
	}
	if seed < 0 {
		seed = -seed
	}
	return Move(seed % 3)
}

func getOrCreate(addr address) *playerState {
	key := addr.String()
	if v := players.Get(key); v != nil {
		return v.(*playerState)
	}
	ps := &playerState{}
	players.Set(key, ps)
	return ps
}

// Throw plays one round of the caller's current match, starting a fresh
// match if none is in progress. Accepts "rock"/"paper"/"scissors" or the
// single-letter shorthand "r"/"p"/"s".
func Throw(cur realm, moveStr string) string {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	caller := cur.Previous().Address()

	playerMove, ok := parseMove(moveStr)
	if !ok {
		panic("invalid move: use rock, paper, or scissors (r/p/s)")
	}

	ps := getOrCreate(caller)
	if ps.Active == nil {
		ps.Active = &match{}
	}
	m := ps.Active

	nonce++
	houseMove := pickHouseMove(caller, nonce)
	round := judge(playerMove, houseMove)

	m.Rounds++
	totalRounds++
	ps.RoundsPlayed++

	var roundMsg string
	switch round {
	case 1:
		m.PlayerWins++
		roundMsg = "you win the round"
	case 2:
		m.HouseWins++
		roundMsg = "house wins the round"
	default:
		roundMsg = "round tied"
	}

	out := "round " + strconv.Itoa(m.Rounds) + ": you played " + moveName(playerMove) +
		", house played " + moveName(houseMove) + " -> " + roundMsg +
		" (score " + strconv.Itoa(m.PlayerWins) + "-" + strconv.Itoa(m.HouseWins) + ")"

	if m.PlayerWins >= winsNeeded || m.HouseWins >= winsNeeded {
		ps.Active = nil
		ps.MatchesPlayed++
		playerTookMatch := m.PlayerWins > m.HouseWins
		if playerTookMatch {
			ps.MatchWins++
			if ps.MatchWins > championWins {
				championWins = ps.MatchWins
				champion = caller
			}
			out += ". MATCH WON!"
		} else {
			ps.MatchLosses++
			out += ". match lost."
		}
		chain.Emit("MatchFinished",
			"player", caller.String(),
			"playerWins", strconv.Itoa(m.PlayerWins),
			"houseWins", strconv.Itoa(m.HouseWins),
		)
	}

	chain.Emit("RoundPlayed",
		"player", caller.String(),
		"playerMove", moveName(playerMove),
		"houseMove", moveName(houseMove),
		"result", strconv.Itoa(round),
	)

	return out
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Rock-Paper-Scissors Arena\n\n")
	b.WriteString("Best-of-three matches against the house. First to " +
		strconv.Itoa(winsNeeded) + " round wins takes the match.\n\n")
	b.WriteString("- Total rounds played: " + strconv.Itoa(totalRounds) + "\n")

	if champion.IsValid() {
		b.WriteString("- Reigning champion: `" + champion.String() +
			"` (" + strconv.Itoa(championWins) + " match wins)\n")
	} else {
		b.WriteString("- No champion yet — be the first to win a match.\n")
	}

	b.WriteString("\n## How to play\n\n")
	b.WriteString("Call `Throw(\"rock\"|\"paper\"|\"scissors\")` (or `r`/`p`/`s`). " +
		"Your throw starts a new match if you don't have one in progress, " +
		"and each call plays one round of it.\n\n")
	b.WriteString("View your own record at this realm's path plus your address, " +
		"e.g. `.../rpsmatch:g1youraddress...`\n")
	return b.String()
}

// escapeInline neutralizes markdown-active characters in untrusted text
// before it's embedded inline in Render output.
func escapeInline(s string) string {
	r := strings.NewReplacer(
		"\\", "\\\\",
		"`", "\\`",
		"*", "\\*",
		"_", "\\_",
		"[", "\\[",
		"]", "\\]",
		"|", "\\|",
	)
	return r.Replace(s)
}

func renderPlayer(rawAddr string) string {
	addr := strings.TrimSpace(rawAddr)
	safe := escapeInline(addr)

	v := players.Get(addr)
	if v == nil {
		return "# Player " + safe + "\n\nNo recorded throws yet.\n"
	}
	ps := v.(*playerState)

	var b strings.Builder
	b.WriteString("# Player " + safe + "\n\n")
	b.WriteString("- Matches won: " + strconv.Itoa(ps.MatchWins) + "\n")
	b.WriteString("- Matches lost: " + strconv.Itoa(ps.MatchLosses) + "\n")
	b.WriteString("- Matches played: " + strconv.Itoa(ps.MatchesPlayed) + "\n")
	b.WriteString("- Rounds played: " + strconv.Itoa(ps.RoundsPlayed) + "\n")

	if ps.Active != nil {
		b.WriteString("\n**Match in progress:** " + strconv.Itoa(ps.Active.PlayerWins) +
			"-" + strconv.Itoa(ps.Active.HouseWins) + " through " +
			strconv.Itoa(ps.Active.Rounds) + " round(s).\n")
	}
	return b.String()
}

// Render shows the arena dashboard at "", or one player's record when path
// is their bech32 address.
func Render(path string) string {
	path = strings.TrimPrefix(strings.TrimSpace(path), "/")
	if path == "" {
		return renderHome()
	}
	return renderPlayer(path)
}

// Package rpsoracle is a rock-paper-scissors opponent that doesn't roll
// dice: it studies each player's move history and always throws the
// counter to whichever move that player has favored most. Play a fixed
// pattern and the oracle punishes it; play close to a uniform 1/3-1/3-1/3
// mix and it can't out-guess you better than chance.
package rpsoracle

import (
	"strconv"
	"strings"

	"chain"
	"chain/runtime"

	"gno.land/p/nt/avl/v0"
)

// Move is one of rock, paper, or scissors, ordered so that
// (winner - loser + 3) % 3 == 1 for every winning pair.
type Move int

const (
	Rock Move = iota
	Paper
	Scissors
)

func moveName(m Move) string {
	switch m {
	case Rock:
		return "rock"
	case Paper:
		return "paper"
	case Scissors:
		return "scissors"
	default:
		return "?"
	}
}

func parseMove(s string) (Move, bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "rock", "r":
		return Rock, true
	case "paper", "p":
		return Paper, true
	case "scissors", "s":
		return Scissors, true
	default:
		return 0, false
	}
}

// judge returns 0 for a tie, 1 if p beats h, 2 if h beats p.
func judge(p, h Move) int {
	return (int(p) - int(h) + 3) % 3
}

// beats returns the move that defeats m.
func beats(m Move) Move {
	return Move((int(m) + 1) % 3)
}

// playerState is the persisted record for one address.
type playerState struct {
	Counts     [3]int // history tally per move, what the oracle predicts from
	Rounds     int
	Wins       int // player beat the oracle
	Losses     int // oracle beat the player
	Draws      int
	BestStreak int
	streak     int // current player win streak against the oracle
}

var (
	players avl.Tree // address string -> *playerState

	nonce         int
	totalRounds   int
	oracleCorrect int // rounds the oracle won by successfully countering

	topOutwitter     address
	topOutwitterWins int
)

func getOrCreate(addr address) *playerState {
	key := addr.String()
	if v := players.Get(key); v != nil {
		return v.(*playerState)
	}
	ps := &playerState{}
	players.Set(key, ps)
	return ps
}

// predict guesses the player's next move as the most-played move in their
// history so far. Ties (including a fresh player's all-zero history) fall
// back to a chain-height-derived seed so the oracle doesn't always break
// ties the same way.
func predict(ps *playerState, seed int64) Move {
	best := Rock
	bestCount := ps.Counts[Rock]
	tied := []Move{Rock}
	for _, m := range []Move{Paper, Scissors} {
		switch {
		case ps.Counts[m] > bestCount:
			bestCount = ps.Counts[m]
			best = m
			tied = []Move{m}
		case ps.Counts[m] == bestCount:
			tied = append(tied, m)
		}
	}
	if len(tied) > 1 {
		if seed < 0 {
			seed = -seed
		}
		best = tied[int(seed)%len(tied)]
	}
	return best
}

// Play pits the caller against the oracle: it predicts your next move from
// your own move history and throws the counter. Accepts
// "rock"/"paper"/"scissors" or the single-letter shorthand "r"/"p"/"s".
func Play(cur realm, moveStr string) string {
	if !cur.IsCurrent() {
		panic("invalid realm")
	}
	caller := cur.Previous().Address()

	playerMove, ok := parseMove(moveStr)
	if !ok {
		panic("invalid move: use rock, paper, or scissors (r/p/s)")
	}

	ps := getOrCreate(caller)

	nonce++
	seed := runtime.ChainHeight() + int64(nonce)
	predicted := predict(ps, seed)
	oracleMove := beats(predicted)

	result := judge(playerMove, oracleMove)

	ps.Counts[playerMove]++
	ps.Rounds++
	totalRounds++

	var msg string
	switch result {
	case 1:
		ps.Wins++
		ps.streak++
		if ps.streak > ps.BestStreak {
			ps.BestStreak = ps.streak
		}
		if ps.Wins > topOutwitterWins {
			topOutwitterWins = ps.Wins
			topOutwitter = caller
		}
		msg = "you outwitted the oracle!"
	case 2:
		ps.Losses++
		ps.streak = 0
		oracleCorrect++
		msg = "the oracle read you like a book."
	default:
		ps.Draws++
		ps.streak = 0
		msg = "a draw — you and the oracle picked the same move."
	}

	chain.Emit("RoundPlayed",
		"player", caller.String(),
		"playerMove", moveName(playerMove),
		"oraclePredicted", moveName(predicted),
		"oracleMove", moveName(oracleMove),
		"result", strconv.Itoa(result),
	)

	return "you played " + moveName(playerMove) + ", the oracle predicted " +
		moveName(predicted) + " and threw " + moveName(oracleMove) + " -> " + msg
}

func renderHome() string {
	var b strings.Builder
	b.WriteString("# Rock-Paper-Scissors Oracle\n\n")
	b.WriteString("An adaptive opponent: it doesn't roll dice, it studies you. ")
	b.WriteString("Every throw is logged, and the oracle always counters whichever ")
	b.WriteString("move you've played most often. Play a uniform mixed strategy and ")
	b.WriteString("it can't out-guess you; fall into a habit and it will.\n\n")

	b.WriteString("- Total rounds played: " + strconv.Itoa(totalRounds) + "\n")
	if totalRounds > 0 {
		pct := oracleCorrect * 100 / totalRounds
		b.WriteString("- Oracle win rate: " + strconv.Itoa(pct) + "%\n")
	}
	if topOutwitter.IsValid() {
		b.WriteString("- Top outwitter: `" + topOutwitter.String() + "` (" +
			strconv.Itoa(topOutwitterWins) + " wins against the oracle)\n")
	} else {
		b.WriteString("- No one has beaten the oracle yet.\n")
	}

	b.WriteString("\n## How to play\n\n")
	b.WriteString("Call `Play(\"rock\"|\"paper\"|\"scissors\")` (or `r`/`p`/`s`). ")
	b.WriteString("View your own record at this realm's path plus your address, ")
	b.WriteString("e.g. `.../rpsoracle:g1youraddress...`\n")
	return b.String()
}

// escapeInline neutralizes markdown-active characters in untrusted text
// before it's embedded inline in Render output.
func escapeInline(s string) string {
	r := strings.NewReplacer(
		"\\", "\\\\",
		"`", "\\`",
		"*", "\\*",
		"_", "\\_",
		"[", "\\[",
		"]", "\\]",
		"|", "\\|",
	)
	return r.Replace(s)
}

func renderPlayer(rawAddr string) string {
	addr := strings.TrimSpace(rawAddr)
	safe := escapeInline(addr)

	v := players.Get(addr)
	if v == nil {
		return "# Player " + safe + "\n\nNo recorded rounds yet.\n"
	}
	ps := v.(*playerState)

	var b strings.Builder
	b.WriteString("# Player " + safe + "\n\n")
	b.WriteString("- Rounds played: " + strconv.Itoa(ps.Rounds) + "\n")
	b.WriteString("- Beat the oracle: " + strconv.Itoa(ps.Wins) + "\n")
	b.WriteString("- Lost to the oracle: " + strconv.Itoa(ps.Losses) + "\n")
	b.WriteString("- Draws: " + strconv.Itoa(ps.Draws) + "\n")
	b.WriteString("- Best win streak vs oracle: " + strconv.Itoa(ps.BestStreak) + "\n")
	b.WriteString("- Move history — rock: " + strconv.Itoa(ps.Counts[Rock]) +
		", paper: " + strconv.Itoa(ps.Counts[Paper]) +
		", scissors: " + strconv.Itoa(ps.Counts[Scissors]) + "\n")

	if ps.Rounds > 0 {
		maxCount := ps.Counts[Rock]
		for _, c := range ps.Counts[1:] {
			if c > maxCount {
				maxCount = c
			}
		}
		predictability := maxCount * 100 / ps.Rounds
		b.WriteString("- Predictability score: " + strconv.Itoa(predictability) +
			"% (lower is harder for the oracle to read)\n")
	}
	return b.String()
}

// Render shows the oracle's dashboard at "", or one player's record when
// path is their bech32 address.
func Render(path string) string {
	path = strings.TrimPrefix(strings.TrimSpace(path), "/")
	if path == "" {
		return renderHome()
	}
	return renderPlayer(path)
}

// Package stack is an educational data-structure playground that keeps BOTH a
// LIFO stack and a FIFO queue of ints, so you can compare how the two behave.
package stack

import (
	"chain"
	"strconv"
	"strings"
)

// stackData holds the LIFO stack; the last pushed element is the "top".
var stackData []int

// queueData holds the FIFO queue; the oldest enqueued element is the "front".
var queueData []int

// Push adds n to the top of the LIFO stack.
func Push(cur realm, n int) {
	stackData = append(stackData, n)
	chain.Emit("Push", "n", strconv.Itoa(n), "size", strconv.Itoa(len(stackData)))
}

// Pop removes and returns the top element of the LIFO stack.
// It panics (a cross-realm abort) if the stack is empty.
func Pop(cur realm) int {
	if len(stackData) == 0 {
		panic("stack is empty: nothing to pop")
	}
	last := len(stackData) - 1
	n := stackData[last]
	stackData = stackData[:last]
	chain.Emit("Pop", "n", strconv.Itoa(n), "size", strconv.Itoa(len(stackData)))
	return n
}

// Enqueue adds n to the back of the FIFO queue.
func Enqueue(cur realm, n int) {
	queueData = append(queueData, n)
	chain.Emit("Enqueue", "n", strconv.Itoa(n), "size", strconv.Itoa(len(queueData)))
}

// Dequeue removes and returns the front element of the FIFO queue.
// It panics (a cross-realm abort) if the queue is empty.
func Dequeue(cur realm) int {
	if len(queueData) == 0 {
		panic("queue is empty: nothing to dequeue")
	}
	n := queueData[0]
	queueData = queueData[1:]
	chain.Emit("Dequeue", "n", strconv.Itoa(n), "size", strconv.Itoa(len(queueData)))
	return n
}

// StackSize returns the number of elements in the LIFO stack.
func StackSize() int { return len(stackData) }

// QueueSize returns the number of elements in the FIFO queue.
func QueueSize() int { return len(queueData) }

// renderInts formats a slice of ints as a space-separated list, e.g. "1 2 3".
func renderInts(xs []int) string {
	if len(xs) == 0 {
		return "_(empty)_"
	}
	parts := make([]string, len(xs))
	for i, x := range xs {
		parts[i] = strconv.Itoa(x)
	}
	return "`" + strings.Join(parts, " ") + "`"
}

// Render returns a Markdown view of both structures with top/front labeled,
// their sizes, and a one-line explanation of LIFO vs FIFO.
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# Stack & Queue Playground\n\n")
	b.WriteString("A **stack** is LIFO (last in, first out) — the last item pushed is the first popped. ")
	b.WriteString("A **queue** is FIFO (first in, first out) — the first item enqueued is the first dequeued.\n\n")

	b.WriteString("## Stack (LIFO) — size ")
	b.WriteString(strconv.Itoa(len(stackData)))
	b.WriteString("\n\n")
	b.WriteString("Contents (bottom → top): ")
	b.WriteString(renderInts(stackData))
	b.WriteString("\n\n")
	if len(stackData) > 0 {
		b.WriteString("Top: `")
		b.WriteString(strconv.Itoa(stackData[len(stackData)-1]))
		b.WriteString("` — the next `Pop` returns this.\n\n")
	} else {
		b.WriteString("Top: _(none)_ — `Pop` would panic.\n\n")
	}

	b.WriteString("## Queue (FIFO) — size ")
	b.WriteString(strconv.Itoa(len(queueData)))
	b.WriteString("\n\n")
	b.WriteString("Contents (front → back): ")
	b.WriteString(renderInts(queueData))
	b.WriteString("\n\n")
	if len(queueData) > 0 {
		b.WriteString("Front: `")
		b.WriteString(strconv.Itoa(queueData[0]))
		b.WriteString("` — the next `Dequeue` returns this.\n\n")
	} else {
		b.WriteString("Front: _(none)_ — `Dequeue` would panic.\n\n")
	}

	b.WriteString("---\n\n")
	b.WriteString("_Tip: push the same sequence into both, then Pop vs Dequeue to see LIFO reverse it while FIFO preserves order._\n")

	return b.String()
}

package tictactoe

import (
	"chain"
	"chain/runtime/unsafe"
	"errors"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// Cell states.
const (
	empty = 0
	markX = 1
	markO = 2
)

// Game holds a single tic-tac-toe match.
type Game struct {
	id       int
	playerX  address // caller of NewGame
	playerO  address // opponent
	board    [9]int  // 0 empty, 1 X, 2 O
	moves    int     // number of moves played
	turn     int     // markX or markO — whose turn it is
	winner   int     // 0 none, 1 X, 2 O
	draw     bool
	finished bool
}

var (
	games  = avl.NewTree() // id (padded string) -> *Game
	nextID = 1
)

func pad(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 12 {
		s = "0" + s
	}
	return s
}

// NewGame creates a game. Caller is X, opponent is O. Returns the game id.
func NewGame(cur realm, opponent address) int {
	caller := unsafe.PreviousRealm().Address()
	if opponent == caller {
		panic("opponent must differ from caller")
	}
	if !opponent.IsValid() {
		panic("invalid opponent address")
	}
	id := nextID
	nextID++
	g := &Game{
		id:      id,
		playerX: caller,
		playerO: opponent,
		turn:    markX,
	}
	games.Set(pad(id), g)
	chain.Emit("GameCreated", "id", strconv.Itoa(id), "x", caller.String(), "o", opponent.String())
	return id
}

// Move plays cell (0-8) for the calling player. Enforces turn order and rejects taken cells.
func Move(cur realm, gameID int, cell int) {
	v := games.Get(pad(gameID))
	if v == nil {
		panic("game not found")
	}
	g := v.(*Game)
	if g.finished {
		panic("game already finished")
	}
	if cell < 0 || cell > 8 {
		panic("cell out of range (0-8)")
	}
	if g.board[cell] != empty {
		panic("cell already taken")
	}
	caller := unsafe.PreviousRealm().Address()

	var mark int
	switch caller {
	case g.playerX:
		mark = markX
	case g.playerO:
		mark = markO
	default:
		panic("caller is not a player in this game")
	}
	if mark != g.turn {
		panic("not your turn")
	}

	g.board[cell] = mark
	g.moves++

	if won(g.board, mark) {
		g.winner = mark
		g.finished = true
		chain.Emit("GameWon", "id", strconv.Itoa(gameID), "winner", markName(mark))
	} else if g.moves == 9 {
		g.draw = true
		g.finished = true
		chain.Emit("GameDraw", "id", strconv.Itoa(gameID))
	} else {
		if g.turn == markX {
			g.turn = markO
		} else {
			g.turn = markX
		}
		chain.Emit("Move", "id", strconv.Itoa(gameID), "cell", strconv.Itoa(cell), "mark", markName(mark))
	}
}

var lines = [8][3]int{
	{0, 1, 2}, {3, 4, 5}, {6, 7, 8}, // rows
	{0, 3, 6}, {1, 4, 7}, {2, 5, 8}, // cols
	{0, 4, 8}, {2, 4, 6}, // diagonals
}

func won(b [9]int, mark int) bool {
	for _, l := range lines {
		if b[l[0]] == mark && b[l[1]] == mark && b[l[2]] == mark {
			return true
		}
	}
	return false
}

func markName(m int) string {
	switch m {
	case markX:
		return "X"
	case markO:
		return "O"
	default:
		return "-"
	}
}

func cellGlyph(m int) string {
	switch m {
	case markX:
		return "X"
	case markO:
		return "O"
	default:
		return "·"
	}
}

// GetGame returns a game by id (read helper for tests / callers).
func GetGame(id int) (*Game, error) {
	v := games.Get(pad(id))
	if v == nil {
		return nil, errors.New("game not found")
	}
	return v.(*Game), nil
}

func renderBoard(b [9]int) string {
	var sb strings.Builder
	for r := 0; r < 3; r++ {
		sb.WriteString("| ")
		for c := 0; c < 3; c++ {
			sb.WriteString(cellGlyph(b[r*3+c]))
			sb.WriteString(" | ")
		}
		sb.WriteString("\n")
	}
	return sb.String()
}

func gameStatus(g *Game) string {
	if g.finished {
		if g.draw {
			return "Draw."
		}
		return "Winner: " + markName(g.winner)
	}
	return "Turn: " + markName(g.turn)
}

// Render draws the list of games, or a single game board at path "/<id>".
func Render(path string) string {
	p := strings.TrimPrefix(path, "/")
	if p == "" {
		return renderList()
	}
	id, err := strconv.Atoi(p)
	if err != nil {
		return "# Tic-Tac-Toe\n\nInvalid game id: " + p + "\n"
	}
	g, gerr := GetGame(id)
	if gerr != nil {
		return "# Tic-Tac-Toe\n\nGame " + p + " not found.\n"
	}
	var sb strings.Builder
	sb.WriteString("# Tic-Tac-Toe — Game #")
	sb.WriteString(strconv.Itoa(g.id))
	sb.WriteString("\n\n")
	sb.WriteString("- X: `")
	sb.WriteString(g.playerX.String())
	sb.WriteString("`\n- O: `")
	sb.WriteString(g.playerO.String())
	sb.WriteString("`\n\n")
	sb.WriteString(renderBoard(g.board))
	sb.WriteString("\n**")
	sb.WriteString(gameStatus(g))
	sb.WriteString("**\n\nCell indices:\n\n")
	sb.WriteString("| 0 | 1 | 2 |\n| 3 | 4 | 5 |\n| 6 | 7 | 8 |\n")
	return sb.String()
}

func renderList() string {
	var sb strings.Builder
	sb.WriteString("# Tic-Tac-Toe\n\n")
	sb.WriteString("2-player tic-tac-toe. Call `NewGame(opponent)` to start; view a game at `/<id>`.\n\n")
	if games.Size() == 0 {
		sb.WriteString("_No games yet._\n")
		return sb.String()
	}
	sb.WriteString("| # | X | O | Status |\n|---|---|---|--------|\n")
	games.Iterate("", "", func(key string, value interface{}) bool {
		g := value.(*Game)
		sb.WriteString("| ")
		sb.WriteString(strconv.Itoa(g.id))
		sb.WriteString(" | `")
		sb.WriteString(g.playerX.String())
		sb.WriteString("` | `")
		sb.WriteString(g.playerO.String())
		sb.WriteString("` | ")
		sb.WriteString(gameStatus(g))
		sb.WriteString(" |\n")
		return false
	})
	return sb.String()
}

// Package todos is a shared, on-chain to-do board realm.
//
// Anyone can add an item; the caller's address is recorded as the author.
// Items can be toggled (open/done) or removed. Render exposes the board as
// Markdown checkboxes with open/done counts, newest item first.
package todos

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// item is one entry on the board. `address` is the uverse bech32 type — it is
// persistable (unlike a `realm` value), so it is safe to store across txs.
type item struct {
	id     int
	text   string
	done   bool
	author address
}

var (
	// items is keyed by zero-padded id string so avl iteration is ordered by id.
	items  avl.Tree
	nextID int
)

// Add appends a new item authored by the caller and returns its id.
//
// Crossing function: takes `cur realm` first (gno 0.9 interrealm convention),
// authenticates with cur.IsCurrent() before trusting cur.Previous().
func Add(cur realm, text string) int {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	text = strings.TrimSpace(text)
	if text == "" {
		panic("todos: text must not be empty")
	}

	author := cur.Previous().Address()

	nextID++
	id := nextID
	items.Set(idKey(id), &item{
		id:     id,
		text:   text,
		done:   false,
		author: author,
	})
	return id
}

// Toggle flips the done state of the item with the given id.
func Toggle(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	v := items.Get(idKey(id))
	if v == nil {
		panic("todos: item not found: #" + strconv.Itoa(id))
	}
	it := v.(*item)
	it.done = !it.done
}

// Remove deletes the item with the given id.
func Remove(cur realm, id int) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	if _, removed := items.Remove(idKey(id)); !removed {
		panic("todos: item not found: #" + strconv.Itoa(id))
	}
}

// idKey renders an id as a fixed-width, zero-padded key so avl.Tree's
// byte-lexicographic ordering matches numeric id ordering.
func idKey(id int) string {
	s := strconv.Itoa(id)
	const width = 12
	if len(s) >= width {
		return s
	}
	return strings.Repeat("0", width-len(s)) + s
}

// shortAddr renders an address as "g1abc…" (first 6 chars + ellipsis).
func shortAddr(a address) string {
	s := a.String()
	if len(s) <= 6 {
		return s
	}
	return s[:6] + "…"
}

// counts returns the number of open and done items.
func counts() (open, done int) {
	items.Iterate("", "", func(_ string, v interface{}) bool {
		if v.(*item).done {
			done++
		} else {
			open++
		}
		return false
	})
	return open, done
}

// Render returns the board as Markdown. Newest item (highest id) first.
//
// Render is NOT a crossing function (no `cur realm` param) — it is read-only
// and invoked by gnoweb, not via MsgCall.
func Render(path string) string {
	open, done := counts()

	var b strings.Builder
	b.WriteString("# Shared To-Do Board\n\n")
	b.WriteString(strconv.Itoa(open) + " open · ")
	b.WriteString(strconv.Itoa(done) + " done · ")
	b.WriteString(strconv.Itoa(open+done) + " total\n\n")

	if open+done == 0 {
		b.WriteString("_No items yet. Add one with `Add(text)`._\n")
		return b.String()
	}

	// Collect in ascending id order, then emit newest first.
	var lines []string
	items.Iterate("", "", func(_ string, v interface{}) bool {
		it := v.(*item)
		mark := " "
		if it.done {
			mark = "x"
		}
		line := "- [" + mark + "] #" + strconv.Itoa(it.id) + " " +
			it.text + " (" + shortAddr(it.author) + ")"
		lines = append(lines, line)
		return false
	})

	for i := len(lines) - 1; i >= 0; i-- {
		b.WriteString(lines[i])
		b.WriteString("\n")
	}

	return b.String()
}

// Package urlshort is a simple on-chain URL alias registry.
//
// Callers register an `alias -> url` mapping they own. An alias can only be
// claimed once; the owner may later update the target URL, but nobody else can
// overwrite an alias they do not own. A per-alias click counter is bumped every
// time the alias is resolved through Render("/<alias>").
package urlshort

import (
	"strings"

	"chain"
	"chain/runtime/unsafe"

	"gno.land/p/nt/avl/v0"
)

// entry is the persisted record for a single alias.
type entry struct {
	url    string
	owner  address
	note   string
	clicks int
}

// aliases maps alias (string) -> *entry, kept in an avl.Tree for deterministic
// iteration order in Render.
var aliases avl.Tree

// isAlphanumeric reports whether s is non-empty and made only of [0-9A-Za-z].
func isAlphanumeric(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		switch {
		case c >= '0' && c <= '9':
		case c >= 'a' && c <= 'z':
		case c >= 'A' && c <= 'Z':
		default:
			return false
		}
	}
	return true
}

// Shorten registers `alias -> url` owned by the caller.
//
// Rules:
//   - alias must be non-empty and alphanumeric;
//   - url must be non-empty;
//   - if the alias is unclaimed, it is created owned by the caller;
//   - if it is already claimed by the caller, the url/note are updated;
//   - if it is claimed by someone else, the call aborts.
func Shorten(cur realm, alias string, url string, note string) {
	if !isAlphanumeric(alias) {
		panic("alias must be non-empty and alphanumeric")
	}
	if url == "" {
		panic("url must be non-empty")
	}

	caller := unsafe.PreviousRealm().Address()

	if v := aliases.Get(alias); v != nil {
		e := v.(*entry)
		if e.owner != caller {
			panic("alias already taken by another owner")
		}
		e.url = url
		e.note = note
		chain.Emit("AliasUpdated", "alias", alias, "owner", caller.String())
		return
	}

	e := &entry{url: url, owner: caller, note: note, clicks: 0}
	aliases.Set(alias, e)
	chain.Emit("AliasCreated", "alias", alias, "owner", caller.String())
}

// Remove deletes an alias owned by the caller. Aborts if the alias does not
// exist or the caller is not the owner.
func Remove(cur realm, alias string) {
	v := aliases.Get(alias)
	if v == nil {
		panic("alias not found")
	}
	e := v.(*entry)
	caller := unsafe.PreviousRealm().Address()
	if e.owner != caller {
		panic("only the owner can remove an alias")
	}
	aliases.Remove(alias)
	chain.Emit("AliasRemoved", "alias", alias, "owner", caller.String())
}

// Lookup returns the target url for an alias and whether it exists. It is a
// read-only helper and does NOT increment the click counter.
func Lookup(alias string) (string, bool) {
	v := aliases.Get(alias)
	if v == nil {
		return "", false
	}
	return v.(*entry).url, true
}

// Render renders Markdown. The root path lists every alias; "/<alias>" shows a
// single alias detail and bumps its click counter.
func Render(path string) string {
	if path == "" || path == "/" {
		return renderIndex()
	}

	alias := strings.TrimPrefix(path, "/")
	v := aliases.Get(alias)
	if v == nil {
		return "# URL Shortener\n\nNo alias named `" + alias + "`.\n\n[← all aliases](/)\n"
	}

	e := v.(*entry)
	e.clicks++

	var b strings.Builder
	b.WriteString("# 🔗 " + alias + "\n\n")
	b.WriteString("**Target:** <" + e.url + ">\n\n")
	b.WriteString("**Owner:** " + e.owner.String() + "\n\n")
	if e.note != "" {
		b.WriteString("**Note:** " + e.note + "\n\n")
	}
	b.WriteString("**Clicks:** " + itoa(e.clicks) + "\n\n")
	b.WriteString("[← all aliases](/)\n")
	return b.String()
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# 🔗 URL Shortener\n\n")

	if aliases.Size() == 0 {
		b.WriteString("_No aliases registered yet._\n\n")
		b.WriteString("Call `Shorten(alias, url, note)` to register one.\n")
		return b.String()
	}

	b.WriteString("| Alias | Target | Owner | Clicks |\n")
	b.WriteString("|-------|--------|-------|--------|\n")
	aliases.Iterate("", "", func(key string, value interface{}) bool {
		e := value.(*entry)
		b.WriteString("| [" + key + "](/" + key + ") | <" + e.url + "> | " +
			short(e.owner.String()) + " | " + itoa(e.clicks) + " |\n")
		return false
	})
	b.WriteString("\nTotal aliases: " + itoa(aliases.Size()) + "\n")
	return b.String()
}

// short truncates a long address for the index table.
func short(s string) string {
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// itoa converts a non-negative int to its decimal string without importing
// strconv (kept minimal & deterministic).
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

// Package vestoken is a fungible token where new supply is never handed out
// instantly — it ports the idea behind Solidity's VestingWallet / linear
// token-streaming contracts (e.g. Sablier) into a single gno.land realm.
//
// MintVested opens a linear vesting grant instead of crediting a balance
// directly. The beneficiary calls Claim over time to pull whatever has
// unlocked so far into their liquid, transferable balance. State is
// package-level and persistent; state-mutating functions are crossing
// functions (`cur realm`) per the gno 0.9 interrealm convention.
package vestoken

import (
	"chain/runtime"
	"errors"
	"sort"
	"strconv"
	"strings"
)

const (
	name   = "VestToken"
	symbol = "VEST"
)

// grant is one linear vesting schedule: `total` unlocks evenly from `start`
// to `start+duration` (measured in block height), and `claimed` tracks how
// much of the unlocked amount the beneficiary has already pulled.
type grant struct {
	total    uint64
	claimed  uint64
	start    int64
	duration int64
}

var (
	// balances holds liquid, already-claimed tokens — transferable like a
	// normal ERC-20 balance.
	balances = map[address]uint64{}
	// grants holds at most one active vesting schedule per beneficiary.
	grants = map[address]*grant{}
	// totalSupply is every token ever minted (vesting or liquid).
	totalSupply uint64
)

var (
	errZeroAddress   = errors.New("vestoken: zero address")
	errZeroAmount    = errors.New("vestoken: amount must be positive")
	errZeroDuration  = errors.New("vestoken: duration must be positive")
	errGrantActive   = errors.New("vestoken: beneficiary already has an unclaimed grant")
	errNoGrant       = errors.New("vestoken: no active grant for this account")
	errInsufficient  = errors.New("vestoken: insufficient balance")
	errOverflow      = errors.New("vestoken: supply overflow")
	errSpoofedRealm  = errors.New("vestoken: spoofed realm")
	errNotUser       = errors.New("vestoken: caller is not a user account")
)

// caller returns the immediate caller's address for a crossing function,
// enforcing the gno 0.9 authentication primitive: cur must be the live
// crossing frame before its Previous() is trusted.
func caller(cur realm) address {
	if !cur.IsCurrent() {
		panic(errSpoofedRealm)
	}
	prev := cur.Previous()
	if !prev.IsUser() {
		panic(errNotUser)
	}
	return prev.Address()
}

// MintVested opens a new linear vesting grant for `to`: `amount` tokens
// unlock block-by-block over the next `durationBlocks` blocks, starting now.
// A beneficiary may only hold one active grant at a time. Crossing function.
func MintVested(cur realm, to address, amount uint64, durationBlocks int64) {
	_ = caller(cur) // authenticate the crossing frame; anyone may open a grant in this demo
	if !to.IsValid() {
		panic(errZeroAddress)
	}
	if amount == 0 {
		panic(errZeroAmount)
	}
	if durationBlocks <= 0 {
		panic(errZeroDuration)
	}
	if g, ok := grants[to]; ok && g.claimed < g.total {
		panic(errGrantActive)
	}
	if totalSupply+amount < totalSupply {
		panic(errOverflow)
	}
	totalSupply += amount
	grants[to] = &grant{
		total:    amount,
		start:    runtime.ChainHeight(),
		duration: durationBlocks,
	}
}

// Claim pulls whatever has unlocked so far from the caller's grant into
// their liquid balance, and returns how much was claimed. Crossing function.
func Claim(cur realm) uint64 {
	who := caller(cur)
	g, ok := grants[who]
	if !ok {
		panic(errNoGrant)
	}

	unlocked := vestedAmount(g, runtime.ChainHeight())
	claimable := unlocked - g.claimed
	if claimable == 0 {
		return 0
	}

	g.claimed = unlocked
	balances[who] += claimable
	if g.claimed >= g.total {
		delete(grants, who)
	}
	return claimable
}

// vestedAmount computes how much of g has unlocked by the given height.
func vestedAmount(g *grant, height int64) uint64 {
	elapsed := height - g.start
	if elapsed <= 0 {
		return 0
	}
	if elapsed >= g.duration {
		return g.total
	}
	return g.total * uint64(elapsed) / uint64(g.duration)
}

// Transfer moves `amount` of the caller's liquid (already-claimed) balance
// to `to`. Crossing function.
func Transfer(cur realm, to address, amount uint64) {
	from := caller(cur)
	if !to.IsValid() {
		panic(errZeroAddress)
	}
	if amount == 0 {
		return
	}
	if balances[from] < amount {
		panic(errInsufficient)
	}
	balances[from] -= amount
	balances[to] += amount
}

// BalanceOf returns the liquid (claimed, transferable) balance of holder.
func BalanceOf(holder address) uint64 {
	return balances[holder]
}

// GrantOf returns the beneficiary's active grant, if any: total amount,
// amount claimed so far, and the amount currently claimable.
func GrantOf(beneficiary address) (total uint64, claimed uint64, claimable uint64) {
	g, ok := grants[beneficiary]
	if !ok {
		return 0, 0, 0
	}
	unlocked := vestedAmount(g, runtime.ChainHeight())
	return g.total, g.claimed, unlocked - g.claimed
}

// TotalSupply returns every token ever minted, vesting or liquid.
func TotalSupply() uint64 { return totalSupply }

// Name returns the token name.
func Name() string { return name }

// Symbol returns the token symbol.
func Symbol() string { return symbol }

// Render produces the gnoweb Markdown view: metadata, active vesting
// grants, and liquid balances — both tables sorted by address for
// deterministic output. Render is NOT a crossing function.
func Render(path string) string {
	var b strings.Builder

	b.WriteString("# " + name + " (" + symbol + ")\n\n")
	b.WriteString("A linearly-vesting ERC-20-style token on gno.land — ")
	b.WriteString("new supply unlocks block-by-block instead of landing instantly.\n\n")
	b.WriteString("- **Name:** " + name + "\n")
	b.WriteString("- **Symbol:** " + symbol + "\n")
	b.WriteString("- **Total supply:** " + strconv.FormatUint(totalSupply, 10) + "\n")
	b.WriteString("- **Current height:** " + strconv.FormatInt(runtime.ChainHeight(), 10) + "\n\n")

	b.WriteString("## Active grants\n\n")
	grantKeys := sortedAddrKeys(grantAddrs())
	if len(grantKeys) == 0 {
		b.WriteString("_No active grants — call `MintVested` to open one._\n\n")
	} else {
		b.WriteString("| Beneficiary | Total | Claimed | Claimable now |\n")
		b.WriteString("| --- | ---: | ---: | ---: |\n")
		for _, k := range grantKeys {
			g := grants[address(k)]
			unlocked := vestedAmount(g, runtime.ChainHeight())
			b.WriteString("| `" + k + "` | " +
				strconv.FormatUint(g.total, 10) + " | " +
				strconv.FormatUint(g.claimed, 10) + " | " +
				strconv.FormatUint(unlocked-g.claimed, 10) + " |\n")
		}
		b.WriteString("\n")
	}

	b.WriteString("## Liquid balances\n\n")
	balKeys := sortedAddrKeys(balanceAddrs())
	if len(balKeys) == 0 {
		b.WriteString("_No claimed balances yet — call `Claim` once a grant has unlocked._\n")
		return b.String()
	}
	b.WriteString("| Address | Amount |\n")
	b.WriteString("| --- | ---: |\n")
	for _, k := range balKeys {
		b.WriteString("| `" + k + "` | " +
			strconv.FormatUint(balances[address(k)], 10) + " |\n")
	}

	return b.String()
}

func grantAddrs() []string {
	keys := make([]string, 0, len(grants))
	for addr := range grants {
		keys = append(keys, addr.String())
	}
	return keys
}

func balanceAddrs() []string {
	keys := make([]string, 0, len(balances))
	for addr, bal := range balances {
		if bal == 0 {
			continue
		}
		keys = append(keys, addr.String())
	}
	return keys
}

func sortedAddrKeys(keys []string) []string {
	sort.Strings(keys)
	return keys
}

// Package wordle is a daily five-letter word puzzle realm for gno.land.
//
// The day's secret word is picked deterministically from the current block
// height (a "day index"), so every player faces the same word for the same
// span of blocks. Players submit guesses with Guess; each guess is scored
// letter-by-letter with emoji feedback (🟩 correct spot, 🟨 wrong spot,
// ⬜ absent). Render shows the caller's board, attempts left, and rules.
package wordle

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strings"
)

// maxAttempts is the number of guesses a player gets per day.
const maxAttempts = 6

// wordLen is the fixed length of every word / guess.
const wordLen = 5

// blocksPerDay controls how many blocks share the same secret word. Testnet
// blocks are fast, so this is a pragmatic "day" for a demo puzzle rather than
// a wall-clock day. Deterministic: derived only from block height.
const blocksPerDay = 17280

// words is the built-in dictionary of candidate secret words. All entries are
// exactly wordLen lowercase letters.
var words = []string{
	"crane",
	"slate",
	"pride",
	"ghost",
	"lunar",
	"mango",
	"vivid",
	"quilt",
	"brave",
	"flame",
	"storm",
	"pearl",
	"trout",
	"zebra",
	"cabin",
}

// board holds one player's guesses for a given day.
type board struct {
	day     int64
	guesses []string // raw lowercase guessed words, in order
	won     bool
}

// players maps a caller address string to that player's current board.
// A plain map is fine here: keys are addresses, iteration order is never
// used for rendering (we only ever look up the caller's own board).
var players = map[string]*board{}

// dayIndex returns the deterministic day index for a given block height.
func dayIndex(height int64) int64 {
	if height < 0 {
		height = 0
	}
	return height / blocksPerDay
}

// wordForDay returns the secret word for the given day index. Deterministic:
// a pure function of the day index and the built-in dictionary.
func wordForDay(day int64) string {
	n := int64(len(words))
	idx := day % n
	if idx < 0 {
		idx += n
	}
	return words[idx]
}

// currentDay returns today's day index from the chain height.
func currentDay() int64 {
	return dayIndex(runtime.ChainHeight())
}

// score compares a guess against the secret and returns wordLen emoji tiles:
// 🟩 right letter right spot, 🟨 right letter wrong spot, ⬜ letter absent.
// Standard Wordle two-pass scoring so duplicate letters are handled correctly.
func score(guess, secret string) string {
	g := []rune(guess)
	s := []rune(secret)

	tiles := make([]string, wordLen)
	// counts of each secret letter still available to match as 🟨.
	counts := map[rune]int{}

	// First pass: greens.
	for i := 0; i < wordLen; i++ {
		if g[i] == s[i] {
			tiles[i] = "🟩"
		} else {
			counts[s[i]]++
		}
	}
	// Second pass: yellows / greys.
	for i := 0; i < wordLen; i++ {
		if tiles[i] == "🟩" {
			continue
		}
		if counts[g[i]] > 0 {
			tiles[i] = "🟨"
			counts[g[i]]--
		} else {
			tiles[i] = "⬜"
		}
	}
	return strings.Join(tiles, "")
}

// isFiveLetters reports whether w is exactly wordLen ASCII lowercase letters.
func isFiveLetters(w string) bool {
	if len(w) != wordLen {
		return false
	}
	for i := 0; i < len(w); i++ {
		c := w[i]
		if c < 'a' || c > 'z' {
			return false
		}
	}
	return true
}

// Guess records a five-letter guess for the caller against today's word.
//
// It is a crossing (state-mutating) function: callers invoke it as
// Guess(cross(cur), "crane"). Identity is taken from the live crossing frame
// after the IsCurrent authentication check.
func Guess(cur realm, word string) {
	if !cur.IsCurrent() {
		panic("spoofed realm")
	}
	caller := cur.Previous().Address().String()

	word = strings.ToLower(strings.TrimSpace(word))
	if !isFiveLetters(word) {
		panic("guess must be exactly 5 lowercase letters a-z")
	}

	day := currentDay()
	b := players[caller]
	if b == nil || b.day != day {
		// New player, or a new day rolled over: reset the board.
		b = &board{day: day}
		players[caller] = b
	}

	if b.won {
		panic("you already solved today's word")
	}
	if len(b.guesses) >= maxAttempts {
		panic("no attempts left today")
	}

	b.guesses = append(b.guesses, word)
	if word == wordForDay(day) {
		b.won = true
	}
}

// Render returns the caller's board as Markdown. It is NOT a crossing function
// (no cur realm parameter). It reads the viewer via the stack-walking
// unsafe.PreviousRealm(); an unknown viewer simply sees an empty board.
func Render(path string) string {
	viewer := unsafe.PreviousRealm().Address().String()
	day := currentDay()

	var sb strings.Builder
	sb.WriteString("# 🟩 Daily Word Puzzle\n\n")
	sb.WriteString("A Wordle-like game. Everyone gets the same secret 5-letter word each ")
	sb.WriteString("\"day\" (a span of blocks). You have ")
	sb.WriteString(itoa(maxAttempts))
	sb.WriteString(" attempts.\n\n")

	sb.WriteString("**Day #")
	sb.WriteString(i64toa(day))
	sb.WriteString("**\n\n")

	b := players[viewer]
	if b == nil || b.day != day {
		sb.WriteString("_No guesses yet today._\n\n")
		writeRules(&sb)
		return sb.String()
	}

	secret := wordForDay(day)
	sb.WriteString("## Your board\n\n")
	for _, g := range b.guesses {
		sb.WriteString(score(g, secret))
		sb.WriteString("  `")
		sb.WriteString(strings.ToUpper(g))
		sb.WriteString("`\n\n")
	}

	left := maxAttempts - len(b.guesses)
	switch {
	case b.won:
		sb.WriteString("🎉 **You solved it!** Come back next day for a new word.\n\n")
	case left <= 0:
		sb.WriteString("💀 **Out of attempts.** The word was `")
		sb.WriteString(strings.ToUpper(secret))
		sb.WriteString("`. Try again next day.\n\n")
	default:
		sb.WriteString("**Attempts left:** ")
		sb.WriteString(itoa(left))
		sb.WriteString("\n\n")
	}

	writeRules(&sb)
	return sb.String()
}

// writeRules appends the legend / how-to-play block.
func writeRules(sb *strings.Builder) {
	sb.WriteString("## Rules\n\n")
	sb.WriteString("- Guess the 5-letter word in ")
	sb.WriteString(itoa(maxAttempts))
	sb.WriteString(" tries: `Guess(\"crane\")`.\n")
	sb.WriteString("- 🟩 correct letter, correct spot.\n")
	sb.WriteString("- 🟨 correct letter, wrong spot.\n")
	sb.WriteString("- ⬜ letter not in the word.\n")
	sb.WriteString("- The word changes every day (deterministic from block height).\n")
}

// itoa formats a small non-negative int (attempt counts) without importing
// strconv, keeping the dependency surface minimal.
func itoa(n int) string {
	return i64toa(int64(n))
}

// i64toa formats an int64 as decimal.
func i64toa(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var digits []byte
	for n > 0 {
		digits = append(digits, byte('0'+n%10))
		n /= 10
	}
	// reverse
	for i, j := 0, len(digits)-1; i < j; i, j = i+1, j-1 {
		digits[i], digits[j] = digits[j], digits[i]
	}
	if neg {
		return "-" + string(digits)
	}
	return string(digits)
}
